/* Series glossary schema v1: ko, en, abbr, def, chapters[]; optional category, related, audio, examples, stage.
   This is the source of truth for both the glossary page and prose tooltips. */
window.BOOK_GLOSSARY = {
  version: 1,
  terms: [
    {"ko":"화학적 기계적 평탄화","en":"Chemical Mechanical Planarization (Polishing)","abbr":"CMP","def":"슬러리의 화학 반응으로 표면을 무르게 하고 패드와 연마입자의 기계 작용으로 깎아 웨이퍼를 평탄하게 만드는 공정. 1980년대 후반 다층 배선의 전역 평탄화를 위해 도입되어 STI·W 플러그·구리 다마신·하이브리드 본딩까지 넓어졌다.","chapters":["overview#principle","preston"]},
    {"ko":"초점 심도","en":"Depth of Focus","abbr":"DOF","def":"노광 상이 허용 범위 안에서 선명하게 맺히는 광축 방향 범위. DOF ≈ k₂·λ/NA²로 첨단 노광에서는 100 nm 안팎이라 칩 위 표면 높이 차를 수십 nm 이하로 줄여야 한다. CMP가 필요한 근본 이유다.","chapters":["overview#dof","pattern"]},
    {"ko":"컨포멀 증착","en":"conformal deposition","abbr":"","def":"아래 패턴의 모양을 따라 거의 같은 두께로 덮이는 증착(CVD·ALD 등). 층을 쌓을수록 단차가 누적되므로 중간중간 평탄화가 필요해진다.","chapters":["overview#topography","pattern"]},
    {"ko":"평활화","en":"smoothing","abbr":"","def":"모서리와 경사만 완만하게 만들고 높이 차 자체는 남기는 가장 약한 단계의 평탄화. 리플로·SOG가 주로 이 수준에 그친다.","chapters":["overview#planarity"]},
    {"ko":"국부 평탄화","en":"local planarization","abbr":"","def":"수 µm~수십 µm 범위 안에서 단차를 없앤 상태. 그보다 긴 다이 규모의 높이 차(밀도가 다른 블록 사이)는 남을 수 있다.","chapters":["overview#planarity","pattern#topography"]},
    {"ko":"전역 평탄화","en":"global planarization","abbr":"","def":"다이 전체(수 mm) 이상의 범위에서 표면 높이 차가 DOF 예산 안에 드는 상태. 실용적으로는 CMP만이 달성한다.","chapters":["overview#planarity","pattern#topography"]},
    {"ko":"평탄화도","en":"Degree of Planarization","abbr":"DP","def":"DP = 1 − (처리 후 단차 / 처리 전 단차). 1이면 완전 평탄, 0이면 단차가 그대로다. 800 nm 단차가 80 nm로 줄면 DP = 0.9다.","chapters":["overview#planarity","pattern"]},
    {"ko":"리플로","en":"reflow (PSG/BPSG)","abbr":"","def":"인·붕소를 넣은 유리(PSG·BPSG)를 약 800~1,000 °C에서 흘려 단차를 완만하게 하는 옛 평탄화법. 국부 평활화에 그치고 열 예산이 커서 금속 배선 위에는 쓸 수 없다.","chapters":["overview#history"]},
    {"ko":"스핀 온 글라스","en":"Spin-On Glass","abbr":"SOG","def":"액상 실리케이트를 스핀 코팅해 골을 채우고 경화시키는 옛 평탄화법. 보통 에치백과 짝을 이루며 수축·균열·흡습 문제가 있다.","chapters":["overview#history"]},
    {"ko":"에치백","en":"etch-back","abbr":"","def":"평탄한 희생막(레지스트·SOG)을 덮은 뒤 아래 막과 같은 속도로 식각해 표면을 낮추는 평탄화법. 선택비를 1로 맞추기 어렵고 국부 평탄화에 그친다.","chapters":["overview#history","metals#thick"]},
    {"ko":"정반","en":"platen","abbr":"","def":"연마 패드를 붙이고 회전하는 원판. CP-300은 패드 지름 762 mm, 93 rpm으로 돈다. 광학·와전류 종점 센서가 정반 안에 들어간다.","chapters":["overview#tool","kinematics","pad","endpoint"]},
    {"ko":"연마 헤드","en":"polishing head, carrier","abbr":"","def":"웨이퍼를 막이 아래로 향하게 뒤집어 잡고 회전·가압하는 부품. 멤브레인, 리테이너 링, 진공 척으로 이루어지며 CP-300은 87 rpm으로 돈다.","chapters":["overview#tool","kinematics"]},
    {"ko":"리테이너 링","en":"retaining ring","abbr":"","def":"헤드에서 웨이퍼 둘레를 감싸는 링. 웨이퍼가 빠져나가지 않게 막고, 패드를 웨이퍼보다 먼저 눌러 가장자리의 압력 집중(패드 반발)을 줄인다. 마모되는 소모품이다.","chapters":["kinematics#edge","overview"]},
    {"ko":"다중 구역 멤브레인 헤드","en":"multi-zone membrane head","abbr":"","def":"웨이퍼 뒷면을 동심원 구역별 공압으로 누르는 고무막 헤드. CP-300은 중심·중간·외곽·가장자리 4구역으로 반경 방향 제거율 분포를 조절한다.","chapters":["kinematics#multizone","overview","endpoint#profile"]},
    {"ko":"패드 반발","en":"pad rebound","abbr":"","def":"웨이퍼 가장자리에서 눌렸던 패드가 바깥에서 다시 솟아오르며 가장자리 수 mm에 압력이 몰리는 현상. 가장자리 과연마(edge fast)의 원인이며 리테이너 링 압력으로 줄인다.","chapters":["kinematics#edge","overview"]},
    {"ko":"FEOL·MEOL·BEOL","en":"Front / Middle / Back End Of Line","abbr":"","def":"트랜지스터를 만드는 전공정(FEOL), 트랜지스터와 배선을 잇는 콘택(MEOL), 금속 배선층(BEOL)의 구분. STI·POP는 FEOL, W 콘택은 MEOL, 구리 다마신은 BEOL CMP다.","chapters":["overview#flow"]},
    {"ko":"건식 투입·건식 배출","en":"dry-in / dry-out","abbr":"","def":"웨이퍼가 마른 채 장비에 들어와 연마·세정·건조를 모두 마치고 마른 채 나가는 구성. 슬러리가 웨이퍼 위에서 마르지 않도록 연마기와 세정기를 한 장비에 통합한다.","chapters":["overview#sequence","postclean#cleaner"]},
    {"ko":"장비 전단 모듈","en":"Equipment Front End Module","abbr":"EFEM","def":"FOUP을 여는 로드포트와 로봇으로 웨이퍼를 장비 안팎으로 옮기는 앞단 모듈. 자체 FFU로 깨끗한 미니 환경을 유지한다.","chapters":["overview#tool"]},
    {"ko":"시간당 처리량","en":"Wafers Per Hour","abbr":"WPH","def":"장비 한 대가 한 시간에 처리하는 웨이퍼 수. 정반 수·연마 시간·세정 시간 중 가장 느린 단계가 정한다. CP-300은 약 60 WPH.","chapters":["overview#tool","advanced#coo"]},
    {"ko":"제거율","en":"Removal Rate","abbr":"RR","def":"단위 시간당 깎인 막 두께(nm/min). 연마 전후 두께 차를 연마 시간으로 나누며, 웨이퍼 위 여러 점의 평균과 분포(WIWNU)를 함께 본다.","chapters":["preston#preston","overview#metrics"]},
    {"ko":"웨이퍼 내 불균일도","en":"Within-Wafer Non-Uniformity","abbr":"WIWNU","def":"웨이퍼 안 측정점 제거율(또는 잔막)의 표준편차를 평균으로 나눈 값(1σ, %). 가장자리 제외(EE)와 측정점 배치에 따라 값이 달라지므로 정의를 함께 밝힌다. CP-300 목표 3 % 이하.","chapters":["kinematics#wiwnu","overview#metrics"]},
    {"ko":"웨이퍼 간 불균일도","en":"Wafer-To-Wafer Non-Uniformity","abbr":"WTWNU","def":"웨이퍼마다의 평균 제거량(잔막)이 흩어지는 정도. 패드·디스크 수명에 따른 제거율 표류가 주원인이며 종점 검출과 런투런 제어로 줄인다.","chapters":["kinematics#wiwnu","overview","endpoint#apc"]},
    {"ko":"디싱","en":"dishing","abbr":"","def":"넓은 금속 배선이나 넓은 STI 필드 산화막이 주변 막보다 접시처럼 오목하게 더 깎이는 현상. 선폭이 넓을수록, 오버폴리시가 길수록, 패드가 무를수록 커진다. CP-300 목표: 10 µm 배선에서 20 nm 이하.","chapters":["pattern#dishing","overview","copper#dishing","oxide","defects"]},
    {"ko":"이로전","en":"erosion","abbr":"","def":"미세 배선이 빽빽한 영역에서 금속과 유전막이 함께 주변 필드보다 얇아지는 현상. 금속 밀도가 높을수록 유전막이 받는 압력이 커져 심해진다. CP-300 목표: 밀도 50 %에서 15 nm 이하.","chapters":["pattern#dishing","overview","copper#dishing"]},
    {"ko":"공정 비용","en":"Cost of Ownership","abbr":"CoO","def":"웨이퍼 한 장을 처리하는 데 드는 총비용. 장비 감가상각, 소모품(패드·슬러리·디스크·브러시), 유틸리티, 인건비, 수율 손실을 처리량과 가동률로 나눠 계산한다. CMP는 슬러리·패드 비중이 크다.","chapters":["advanced#coo","overview"]},
    {"ko":"프레스턴 식","en":"Preston equation","abbr":"","def":"제거율이 압력과 상대 속도의 곱에 비례한다는 경험식 RR = k_p·P·V. 1927년 F. W. Preston이 유리 연마에서 제안했다. CMP 거동을 이해하는 출발점이지만 문턱·포화·온도 효과에서 휜다.","chapters":["preston#preston","overview","tribology#cof-preston"]},
    {"ko":"프레스턴 계수","en":"Preston coefficient","abbr":"k_p","def":"프레스턴 식의 비례 상수로 단위는 Pa⁻¹(= m²/N). 슬러리 화학·패드·온도를 모두 담는다. CP-300 산화막은 약 1.0×10⁻¹³ Pa⁻¹로 3 psi·1.75 m/s에서 약 220 nm/min이 나온다.","chapters":["preston#preston","overview"]},
    {"ko":"아카드 마모식","en":"Archard wear equation","abbr":"","def":"미끄럼 마모 부피 V = K·F·L/H (K: 마모 계수, F: 하중, L: 미끄럼 거리, H: 경도). 단위 시간·면적으로 나누면 프레스턴 식이 된다. 패드 컨디셔닝의 절삭률 모델에도 쓴다.","chapters":["preston#archard","conditioning#cutrate"]},
    {"ko":"마모 계수","en":"wear coefficient","abbr":"K","def":"아카드 식의 무차원 비례 상수. 미끄럼 거리당 마모 부피를 하중/경도로 나눈 값으로, 화학 반응이 표면을 무르게 하면 실질적으로 커진다.","chapters":["preston#archard"]},
    {"ko":"블랭킷 웨이퍼","en":"blanket wafer","abbr":"","def":"패턴 없이 막만 고르게 증착한 시험 웨이퍼. 제거율·k_p·WIWNU를 패턴 효과 없이 재는 데 쓴다.","chapters":["preston#experiment"]},
    {"ko":"문턱 압력","en":"threshold pressure","abbr":"P_th","def":"이보다 낮은 압력에서는 거의 깎이지 않는 압력. RR = k_p(P − P_th)V 꼴로 쓰며, 세리아 STI 슬러리에서는 다운 영역이 문턱 아래에 머물러 자기 정지와 높은 평탄화 효율을 만든다.","chapters":["preston#nonlinear","oxide#ceria"]},
    {"ko":"비프레스턴 거동","en":"non-Prestonian behavior","abbr":"","def":"제거율이 P·V에 정비례하지 않는 거동. 문턱 압력, 거듭제곱(RR ∝ P^a V^b), 고 PV 포화(화학 율속), 하이드로플레이닝, 온도 상승이 원인이다.","chapters":["preston#nonlinear","oxide"]},
    {"ko":"정적 식각률","en":"Static Etch Rate","abbr":"SER","def":"연마하지 않고 슬러리에 담가만 둘 때의 막 용해 속도. 구리 슬러리에서는 디싱·부식의 지표라 수 nm/min 이하로 억제제를 맞춘다.","chapters":["copper#chem","preston#chemistry"]},
    {"ko":"연화층","en":"chemically softened (hydrated) layer","abbr":"","def":"슬러리와 반응해 표면에 생기는 얇고 무른 층. 산화막은 수화된 실리카층, 구리는 산화물·착물층이다. 화학이 층을 만들고 기계가 걷어 내는 2단계 직렬 과정이 CMP의 기본 그림이다.","chapters":["preston#chemistry","oxide#hydration"]},
    {"ko":"기계 율속","en":"mechanically limited regime","abbr":"","def":"연화층은 충분히 빨리 생기는데 기계적 제거가 느려 RR이 P·V에 비례하는 영역. 낮은 압력·속도에서 나타난다.","chapters":["preston#chemistry","metals#wchem"]},
    {"ko":"화학 율속","en":"chemically (reaction) limited regime","abbr":"","def":"기계 작용은 충분한데 연화층 생성 속도가 따라오지 못해 RR이 P·V를 올려도 포화하는 영역. 이 영역에서는 온도·산화제 농도가 제거율을 좌우한다.","chapters":["preston#chemistry","metals#wchem"]},
    {"ko":"화학–기계 시너지","en":"chemo-mechanical synergy","abbr":"","def":"슬러리로 식각만 할 때와 화학 없이 연마만 할 때의 제거율 합보다 둘을 함께 할 때 제거율이 훨씬 큰 현상. 화학이 표면을 무르게 하고 기계가 반응 생성물을 걷어 새 표면을 드러내기 때문이다.","chapters":["preston#chemistry"]},
    {"ko":"아레니우스 식","en":"Arrhenius equation","abbr":"","def":"반응 속도 상수 k = A·exp(−E_a/RT). 패드 온도가 몇 도만 올라도 화학 율속 영역의 제거율이 수 % 이상 달라진다. 마찰 발열과 결합하면 온도–제거율 되먹임이 생긴다.","chapters":["preston#temperature","tribology#arrhenius"]},
    {"ko":"활성화 에너지","en":"activation energy","abbr":"E_a","def":"반응이 일어나기 위해 넘어야 할 에너지 장벽. 아레니우스 그림(ln RR 대 1/T)의 기울기에서 구한다. CMP 겉보기 활성화 에너지는 보통 수십 kJ/mol 이하로 순수 화학 반응보다 작다.","chapters":["preston#temperature","tribology#arrhenius"]},
    {"ko":"마찰 발열","en":"frictional heating","abbr":"q","def":"단위 면적당 마찰 발열 q = μ·P·V. CP-300 산화막(μ ≈ 0.3)에서 약 11 kW/m², 웨이퍼 전체로 약 0.8 kW이며 패드 온도를 수~십수 °C 올린다.","chapters":["preston#temperature","tribology#heat"]},
    {"ko":"헤르츠 접촉","en":"Hertzian contact","abbr":"","def":"탄성 구와 평면의 접촉 해석. 접촉 반경 a = (3FR/4E*)^(1/3), 압입 깊이 δ = a²/R. 연마입자 하나가 웨이퍼를 수 Å~nm 파고드는 깊이를 추정하는 데 쓴다.","chapters":["preston#contact","defects#mechanics"]},
    {"ko":"유효 탄성률","en":"effective (reduced) modulus","abbr":"E*","def":"두 물체 접촉의 등가 탄성률 1/E* = (1−ν₁²)/E₁ + (1−ν₂²)/E₂. 무른 쪽이 거의 결정하므로 패드–웨이퍼 접촉은 패드 탄성률이, 입자–웨이퍼 접촉은 두 경질 재료가 정한다.","chapters":["preston#contact","pad#contact"]},
    {"ko":"실접촉 면적","en":"real contact area","abbr":"A_r","def":"패드 돌기 끝이 실제로 웨이퍼(와 입자)에 닿는 면적. 겉보기 면적의 1 % 미만이며 하중에 거의 비례해 늘어난다. 하중이 이 작은 면적에 몰려 국소 압력은 수 MPa에 이른다.","chapters":["pad#contact","preston#contact","tribology#film"]},
    {"ko":"활성 연마입자","en":"active abrasive","abbr":"","def":"패드 돌기와 웨이퍼 사이에 끼어 하중을 받으며 실제로 표면을 긁는 입자. 슬러리 속 입자의 극히 일부이며, 압력이 오를수록 더 작은 입자까지 활성이 된다. 큰 입자 꼬리가 스크래치를 만드는 이유이기도 하다.","chapters":["preston#contact","slurry"]},
    {"ko":"그린우드–윌리엄슨 모델","en":"Greenwood–Williamson model","abbr":"GW","def":"거친 표면을 높이가 확률 분포를 따르는 같은 곡률의 돌기 집합으로 보고, 각 돌기에 헤르츠 접촉을 적용해 실접촉 면적과 하중을 구하는 모델(1966). 지수 분포면 실접촉 면적이 하중에 정비례한다.","chapters":["pad#contact","preston#contact"]},
    {"ko":"루오–돈펠드 모델","en":"Luo–Dornfeld model","abbr":"","def":"입자 크기 분포와 패드 돌기의 탄성 변형으로 활성 입자 비율과 압입 깊이를 계산하는 CMP 제거 모델(2001). 제거율이 P^(1/3) 꼴 항을 포함해 프레스턴 식과 다른 압력 의존을 예측한다.","chapters":["preston#contact"]},
    {"ko":"상대 속도","en":"relative velocity","abbr":"v_rel","def":"웨이퍼 한 점이 패드에 대해 미끄러지는 속도. 헤드·정반 각속도가 같으면 웨이퍼 모든 점에서 크기·방향이 같아 |v| = ω·d (d: 정반–웨이퍼 중심 거리)가 된다. CP-300은 약 1.75 m/s.","chapters":["kinematics#velocity","preston"]},
    {"ko":"회전수 비","en":"head-to-platen speed ratio","abbr":"","def":"헤드 rpm과 정반 rpm의 비. 1이면 속도장이 균일하고, 1에서 벗어날수록 반경 방향 속도 차가 생긴다. CP-300(87/93)처럼 살짝 어긋나게 해 궤적이 같은 자리를 반복하지 않게 한다.","chapters":["kinematics#velocity"]},
    {"ko":"궤적","en":"trajectory (epitrochoid)","abbr":"","def":"웨이퍼 위 한 점이 패드 위에 그리는 경로. 두 회전의 합이라 에피트로코이드 꼴이 되며, 궤적 밀도의 고르기가 패드 마모와 제거율 균일도에 영향을 준다.","chapters":["kinematics#trajectory","conditioning#traj"]},
    {"ko":"스윕","en":"sweep, oscillation","abbr":"","def":"헤드(또는 컨디셔너)를 반경 방향으로 왕복시키는 동작. 헤드 스윕은 패드 마모 홈을 평균화하고, 컨디셔너 스윕 레시피(구간별 체류 시간)는 패드 마모 프로파일을 직접 정한다. CP-300 헤드 스윕 ±20 mm.","chapters":["kinematics#trajectory","conditioning#sweep"]},
    {"ko":"오버행","en":"overhang","abbr":"","def":"스윕할 때 웨이퍼 일부가 패드 바깥으로 걸쳐 나가는 것. 그 부분은 접촉이 끊겨 제거율이 줄고 가장자리 압력 분포가 바뀐다. 스윕 진폭의 상한을 정한다.","chapters":["kinematics#trajectory"]},
    {"ko":"가장자리 제외","en":"Edge Exclusion","abbr":"EE","def":"균일도·결함 평가에서 빼는 웨이퍼 가장자리 폭. CP-300은 3 mm. EE를 줄일수록 쓸 수 있는 다이가 늘지만 가장자리 효과가 그대로 드러난다.","chapters":["kinematics#wiwnu"]},
    {"ko":"49점 측정","en":"49-point measurement","abbr":"","def":"웨이퍼 위 동심원 위의 49개 점에서 두께를 재는 표준 측정 배치. 점 배치에 따라 같은 웨이퍼라도 WIWNU 값이 달라진다.","chapters":["kinematics#wiwnu"]},
    {"ko":"가장자리 효과","en":"edge effect","abbr":"","def":"웨이퍼 가장자리 수 mm에서 패드 변형 때문에 압력이 몰리거나 빠져 제거율이 빨라지거나(edge fast) 느려지는(edge slow) 현상. 리테이너 링 압력·가장자리 구역 압력으로 보정한다.","chapters":["kinematics#edge"]},
    {"ko":"가장자리 처짐","en":"edge roll-off","abbr":"","def":"웨이퍼 맨 가장자리 두께(또는 높이)가 안쪽보다 급히 떨어지는 프로파일. 가장자리 과연마가 쌓이거나 원래 기판 모양에서 오며, 하이브리드 본딩 가장자리 접합에도 영향을 준다.","chapters":["kinematics#edge","advanced"]},
    {"ko":"영향 행렬","en":"influence matrix (function)","abbr":"","def":"멤브레인 각 구역 압력을 조금 바꿨을 때 반경별 제거율이 얼마나 바뀌는지 모은 행렬(구역 하나의 열이 영향 함수). 이웃 구역에 번지는 성분이 있어, 원하는 프로파일을 얻으려면 역문제(최소제곱)를 푼다.","chapters":["kinematics#multizone","endpoint#profile"]},
    {"ko":"윙클러·파스테르나크 기초","en":"Winkler / Pasternak foundation","abbr":"","def":"패드를 수직 스프링 층(윙클러)으로, 여기에 이웃 점을 잇는 전단 결합(파스테르나크)을 더해 모델링하는 방법. 가장자리 압력 분포와 패턴 위 압력 전달을 해석적으로 구한다.","chapters":["kinematics#edge","pad#stack"]},
    {"ko":"슬러리 이용률","en":"slurry utilization","abbr":"","def":"공급한 슬러리 중 실제로 패드–웨이퍼 사이를 지나 반응에 참여하는 비율. 원심력으로 대부분이 정반 밖으로 버려져 보통 수십 % 이하이며, 공급 위치·유량·그루브가 정한다.","chapters":["kinematics#slurry","pad#grooves"]},
    {"ko":"연마 패드","en":"polishing pad","abbr":"","def":"정반에 붙여 웨이퍼를 누르고 슬러리를 나르는 고분자 패드. 경도·압축률·기공·그루브가 평탄화 길이와 균일도, 결함을 정한다. CP-300은 경질 폴리우레탄 상부 패드(약 2 mm) + 연질 하부 패드.","chapters":["pad#role","overview"]},
    {"ko":"폴리우레탄","en":"polyurethane","abbr":"PU","def":"이소시아네이트와 폴리올·사슬 연장제가 반응한 고분자. 경질·연질 세그먼트의 비율로 경도와 탄성을 넓게 조절할 수 있어 CMP 패드의 표준 재료다.","chapters":["pad#pu"]},
    {"ko":"경질 세그먼트","en":"hard segment","abbr":"","def":"폴리우레탄 사슬 중 이소시아네이트와 사슬 연장제가 만든 단단한 부분. 수소 결합으로 뭉쳐 물리적 가교점 역할을 하며 패드의 강성과 경도를 담당한다.","chapters":["pad#pu"]},
    {"ko":"연질 세그먼트","en":"soft segment","abbr":"","def":"폴리우레탄 사슬 중 긴 폴리올이 만든 유연한 부분. 유리 전이 온도가 낮아 상온에서 고무처럼 움직이며 탄성과 인성을 준다.","chapters":["pad#pu"]},
    {"ko":"미세상 분리","en":"microphase separation","abbr":"","def":"경질·연질 세그먼트가 서로 섞이지 않고 수~수십 nm 도메인으로 갈라지는 현상. 분리 정도가 탄성률의 온도 의존성을 정한다.","chapters":["pad#pu"]},
    {"ko":"유리 전이 온도","en":"glass transition temperature","abbr":"Tg","def":"고분자가 유리처럼 단단한 상태에서 고무처럼 무른 상태로 바뀌는 온도. 패드 운전 온도(약 30~50 °C)가 전이 영역에 가까우면 온도에 따라 탄성률과 제거율이 크게 변한다.","chapters":["pad#pu","tribology#heat"]},
    {"ko":"저장 탄성률","en":"storage modulus","abbr":"E′","def":"동적 기계 분석(DMA)에서 진동 변형에 대해 탄성적으로 저장되는 성분의 탄성률. 온도에 따라 유리 영역 → 전이 → 고무 평탄역으로 떨어지며, 패드 강성과 평탄화 길이의 지표다.","chapters":["pad#pu"]},
    {"ko":"동적 기계 분석","en":"Dynamic Mechanical Analysis","abbr":"DMA","def":"시편에 작은 진동 변형을 주면서 온도를 올려 저장 탄성률 E′, 손실 탄성률 E″, tan δ를 재는 시험. 패드의 Tg와 온도 민감도를 비교하는 표준 방법이다.","chapters":["pad#pu"]},
    {"ko":"미세 구","en":"hollow polymeric microsphere","abbr":"","def":"패드 기공을 만드는 속이 빈 고분자 구슬(지름 수십 µm). 성형 때 섞어 넣으면 균일한 닫힌 기공이 생기고, 표면에서 잘리면 슬러리를 담는 오목한 주머니가 된다.","chapters":["pad#pores"]},
    {"ko":"기공률","en":"porosity","abbr":"","def":"패드 부피 중 기공이 차지하는 비율(보통 수십 %). 높을수록 패드가 무르고 슬러리를 많이 담지만 강성과 수명이 줄어든다. 단면에서 본 면적 분율이 부피 분율과 같다(입체해석학).","chapters":["pad#pores"]},
    {"ko":"개기공","en":"open pore","abbr":"","def":"패드 표면에서 잘려 위가 열린 기공. 슬러리 저장소이자 연마 부스러기를 받아 두는 곳이며, 글레이징으로 막히면 제거율이 떨어진다.","chapters":["pad#pores","conditioning"]},
    {"ko":"적층 패드","en":"stacked pad","abbr":"","def":"경질 상부 패드와 연질 하부 패드를 겹친 구조. 상부는 다이 규모 평탄화(긴 평탄화 길이)를, 하부는 웨이퍼 규모 굴곡을 따라가 균일도를 맡는다.","chapters":["pad#stack","pattern#planlength"]},
    {"ko":"하부 패드","en":"subpad","abbr":"","def":"적층 패드 아래쪽의 무르고 압축되기 쉬운 층(부직포·폼). 웨이퍼 휨과 두께 변화를 흡수해 WIWNU를 개선하지만 너무 무르면 평탄화 길이가 짧아진다.","chapters":["pad#stack"]},
    {"ko":"쇼어 경도","en":"Shore hardness (D/A)","abbr":"","def":"규정된 압자가 시편에 파고드는 깊이로 매기는 경도(0~100). 경질 패드는 쇼어 D, 연질 패드는 쇼어 A로 표기하며 CP-300 상부 패드는 쇼어 D 약 55~60.","chapters":["pad#stack"]},
    {"ko":"압축률","en":"compressibility","abbr":"","def":"규정 하중에서 패드 두께가 줄어드는 비율(%). 하부 패드가 크고 상부 패드가 작다. 압축률이 클수록 균일도는 좋아지고 평탄화 성능은 나빠진다.","chapters":["pad#stack"]},
    {"ko":"굽힘 길이","en":"bending (elastic) length","abbr":"","def":"패드를 탄성 기초 위의 판으로 볼 때 하중이 퍼지는 특성 길이. 굽힘 강성 ∝ E·t³에 따라 길어지며 평탄화 길이의 물리적 근거가 된다.","chapters":["pad#stack","pattern#planlength"]},
    {"ko":"평탄화 길이","en":"Planarization Length","abbr":"PL","def":"패드가 높이 차를 “느끼는” 특성 거리. 이보다 짧은 거리의 높이 차는 제거되고 긴 것은 남는다. 경질 패드 산화막 CMP에서 대략 2~7 mm이며, 단단하고 두꺼운 패드일수록 길다.","chapters":["pattern#planlength","overview","pad","metals#thick"]},
    {"ko":"돌기","en":"asperity","abbr":"","def":"패드 표면의 미세한 봉우리. 실제 하중은 몇 안 되는 돌기 끝이 받으며, 돌기 높이 분포가 실접촉 면적·제거율·평탄화 효율을 정한다. 컨디셔닝이 돌기를 다시 세운다.","chapters":["pad#contact","conditioning#rough"]},
    {"ko":"그루브","en":"groove (concentric, XY, radial, spiral)","abbr":"","def":"패드 표면에 판 홈. 슬러리를 고르게 나르고, 부스러기를 빼내며, 하이드로플레이닝과 웨이퍼 흡착을 막는다. 동심원은 슬러리를 오래 붙잡고 XY·방사형은 빨리 뺀다. CP-300은 동심원 피치 3 mm·깊이 0.75 mm.","chapters":["pad#grooves","kinematics#slurry"]},
    {"ko":"K-그루브","en":"K-groove (concentric groove)","abbr":"","def":"동심원 그루브를 흔히 부르는 이름. 반지름 방향 통로가 없어 슬러리 체류 시간이 길고 이용률이 높지만 부스러기 배출은 느리다.","chapters":["pad#grooves"]},
    {"ko":"슬러리 체류 시간","en":"slurry residence time","abbr":"","def":"슬러리가 패드–웨이퍼 사이에 머무는 평균 시간. 그루브 형태·정반 속도·유량에 따라 달라지며, 너무 짧으면 반응이 덜 되고 너무 길면 부스러기와 열이 쌓인다.","chapters":["pad#grooves"]},
    {"ko":"하이드로플레이닝","en":"hydroplaning","abbr":"","def":"슬러리 막의 유체 압력이 하중을 떠받쳐 웨이퍼가 패드에서 뜨는 현상(수막 현상). 그루브가 없는 패드에서 속도를 올리면 막이 두꺼워져 제거율이 꺾인다. 그루브가 압력을 빼서 막는다.","chapters":["pad#hydro","tribology#film"]},
    {"ko":"글레이징","en":"glazing","abbr":"","def":"연마 중 패드 돌기가 납작하게 눌리고 기공이 부스러기로 막혀 표면이 매끈해지는 현상. 실접촉 압력과 슬러리 수송이 나빠져 제거율이 시간에 따라 떨어진다. 컨디셔닝이 해결책이다.","chapters":["pad#glazing","conditioning#why","defects"]},
    {"ko":"패드 브레이크인","en":"pad break-in","abbr":"","def":"새 패드를 쓰기 전에 컨디셔닝과 더미 웨이퍼 연마로 표면 성형 층을 걷어 내고 제거율을 안정시키는 길들이기. 끝났는지는 제거율·결함이 안정되는 것으로 판단한다.","chapters":["pad#select","conditioning"]},
    {"ko":"패드 컨디셔닝","en":"pad conditioning, dressing","abbr":"","def":"다이아몬드 디스크로 패드 표면을 긁어 글레이징된 층을 걷고 돌기와 열린 기공을 다시 만드는 작업. 제거율을 안정시키지만 패드를 깎아 수명을 쓴다.","chapters":["conditioning#why","pad#glazing"]},
    {"ko":"인시투·엑스시투 컨디셔닝","en":"in-situ / ex-situ conditioning","abbr":"","def":"연마와 동시에 컨디셔닝하는 인시투, 웨이퍼 사이에만 하는 엑스시투. 인시투는 표면 상태가 일정해 제거율이 안정되지만 패드 소모와 디스크 부스러기가 늘어난다. CP-300은 인시투.","chapters":["conditioning#why"]},
    {"ko":"다이아몬드 디스크","en":"diamond disk (conditioner)","abbr":"","def":"금속 기판에 다이아몬드 입자를 고정한 컨디셔너. 다이아몬드 크기·밀도·배열·돌출 높이·결합 방식이 절삭률과 패드 표면 거칠기, 탈락 위험을 정한다. CP-300은 지름 100 mm, 하중 약 30~45 N.","chapters":["conditioning#disk"]},
    {"ko":"그릿","en":"grit size","abbr":"","def":"다이아몬드 입자 크기 등급(메시 번호 또는 µm). 클수록 절삭률이 높고 표면이 거칠어지며, 작을수록 고운 표면과 낮은 결함을 준다.","chapters":["conditioning#disk"]},
    {"ko":"돌출 높이","en":"diamond protrusion height","abbr":"","def":"다이아몬드가 결합층 위로 솟은 높이. 디스크 안의 산포가 크면 가장 높은 소수의 다이아몬드만 패드를 자르고 하중이 몰려 탈락하기 쉽다.","chapters":["conditioning#disk"]},
    {"ko":"활성 다이아몬드","en":"working diamonds","abbr":"","def":"실제로 패드에 닿아 홈을 파는 다이아몬드. 돌출 높이 산포 때문에 전체의 일부에 불과하며, 그 수가 하중 분배와 절삭률·디스크 수명을 정한다.","chapters":["conditioning#disk"]},
    {"ko":"전착 디스크","en":"electroplated Ni-bond disk","abbr":"","def":"니켈 도금으로 다이아몬드를 기계적으로 붙잡은 디스크. 만들기 쉽지만 화학적 결합이 없어 결합력이 약하고 탈락 위험이 크다.","chapters":["conditioning#disk"]},
    {"ko":"브레이징 디스크","en":"brazed disk","abbr":"","def":"활성 금속 땜납으로 다이아몬드와 화학 결합을 만든 디스크. 결합력이 강해 노출 높이를 키울 수 있고 탈락이 적다.","chapters":["conditioning#disk"]},
    {"ko":"CVD 다이아몬드 코팅","en":"CVD diamond-coated conditioner","abbr":"","def":"가공한 돌기 위에 CVD 다이아몬드 막을 입힌 컨디셔너. 돌기 높이와 배열을 정밀하게 맞출 수 있어 활성 비율과 균일도가 높고 입자 탈락이 거의 없다.","chapters":["conditioning#disk"]},
    {"ko":"패드 절삭률","en":"Pad Cut Rate","abbr":"PCR","def":"컨디셔닝으로 패드 두께가 줄어드는 속도(µm/h). 아카드 식처럼 하중·속도에 비례하고 디스크 마모와 함께 떨어진다. CP-300은 약 20~40 µm/h로 패드 수명 약 1,000~1,500장을 정한다.","chapters":["conditioning#cutrate"]},
    {"ko":"컨디셔너 체류 시간","en":"conditioner dwell time","abbr":"","def":"스윕 레시피에서 디스크가 각 반경 구간에 머무는 시간. 구간별 체류 시간 × 접촉 기하가 반경별 패드 마모량을 정한다.","chapters":["conditioning#sweep"]},
    {"ko":"패드 마모 프로파일","en":"pad wear profile","abbr":"","def":"반지름에 따른 패드 두께 감소 분포. 고르지 않으면 패드가 오목·볼록해져 웨이퍼 제거율 분포가 바뀌므로 스윕 레시피로 평평하게 맞춘다.","chapters":["conditioning#sweep","conditioning#life"]},
    {"ko":"쟁기질·절삭","en":"plowing / cutting","abbr":"","def":"다이아몬드가 패드를 지나며 재료를 옆으로 밀어 올리는 쟁기질과, 칩으로 떼어 내는 절삭. 쟁기질은 새 돌기와 피브릴(거스러미)을 만들고, 절삭은 패드를 깎아 수명을 줄인다.","chapters":["conditioning#mechanism"]},
    {"ko":"피브릴","en":"fibril, burr","abbr":"","def":"다이아몬드가 지나간 홈 가장자리에 남는 고분자 거스러미. 슬러리 입자를 붙잡는 미세 돌기 역할을 해 연마 직후 제거율을 높인다.","chapters":["conditioning#mechanism"]},
    {"ko":"애벗–파이어스톤 곡선","en":"Abbott–Firestone (bearing area) curve","abbr":"","def":"표면 높이 분포의 누적 곡선으로, 높이별로 재료가 차지하는 면적 비율을 보여 준다. 패드 돌기 봉우리·핵심부·골을 Rpk·Rk·Rvk로 나누는 기준이다.","chapters":["conditioning#rough"]},
    {"ko":"Sq","en":"root-mean-square height","abbr":"Sq","def":"면 거칠기의 제곱평균제곱근 높이(ISO 25178). 패드 전체 거칠기 크기를 나타내지만 봉우리와 골을 구별하지 못한다.","chapters":["conditioning#rough"]},
    {"ko":"Rpk","en":"reduced peak height","abbr":"Rpk","def":"애벗 곡선에서 핵심부 위로 솟은 봉우리의 높이(ISO 13565-2). 실제로 웨이퍼에 닿는 돌기의 양을 나타내 제거율과 상관이 크다. 컨디셔닝 직후 크고 글레이징되면 작아진다.","chapters":["conditioning#rough"]},
    {"ko":"Rk·Rvk","en":"core roughness depth / reduced valley depth","abbr":"Rk/Rvk","def":"Rk는 애벗 곡선의 핵심부 깊이, Rvk는 핵심부 아래 골(기공)의 깊이. Rvk는 슬러리를 담는 부피의 지표다.","chapters":["conditioning#rough"]},
    {"ko":"크로스해치","en":"cross-hatch pattern","abbr":"","def":"다이아몬드 궤적이 서로 다른 방향으로 교차하며 패드에 남긴 그물 무늬. 긁기 방향이 고르면 돌기 방향성이 줄어 제거율이 안정된다.","chapters":["conditioning#traj"]},
    {"ko":"다이아몬드 탈락","en":"diamond pull-out","abbr":"","def":"결합이 약하거나 하중이 몰린 다이아몬드가 디스크에서 빠지는 것. 빠진 알은 패드에 박혀 웨이퍼에 활 모양의 연속 스크래치를 남긴다. 탈락률은 다이아몬드 하중의 거듭제곱으로 는다.","chapters":["conditioning#pullout","defects#causes"]},
    {"ko":"번인","en":"conditioner burn-in","abbr":"","def":"새 디스크를 실제 웨이퍼에 쓰기 전에 더미 패드·웨이퍼에서 돌려 결합이 약한 다이아몬드와 제조 부스러기를 미리 털어 내는 작업.","chapters":["conditioning#pullout"]},
    {"ko":"패드 두께 센서","en":"pad thickness sensor","abbr":"","def":"컨디셔너 암의 높이 변위 등으로 패드 두께를 연마 중에 추정하는 센서. 절삭률을 추적해 하중을 보상하고 그루브 깊이가 한계에 이르기 전에 교체 시점을 알린다.","chapters":["conditioning#life"]},
    {"ko":"슬러리","en":"slurry","abbr":"","def":"연마입자, 산화제, 착화제, 부식 방지제, pH 조절제, 계면활성제를 물에 분산한 CMP 소모품. 화학이 표면을 무르게 하고 입자가 걷어 낸다. 산화막은 흄드 실리카 약 12 wt%·pH ~11.","chapters":["slurry#components","overview"]},
    {"ko":"연마입자","en":"abrasive","abbr":"","def":"슬러리 속 고체 입자(실리카·세리아·알루미나). 크기는 수십~수백 nm이며 경도·형상·표면 화학·농도가 제거율과 스크래치를 정한다.","chapters":["slurry#abrasive"]},
    {"ko":"흄드 실리카","en":"fumed silica","abbr":"","def":"SiCl₄를 화염 속에서 가수분해해 만든 실리카. 1차 입자 수~수십 nm가 사슬처럼 뭉친 응집체(약 100~200 nm)로 산화막 연마력이 크지만 큰 입자 꼬리가 생기기 쉽다.","chapters":["slurry#abrasive","oxide#hydration"]},
    {"ko":"콜로이달 실리카","en":"colloidal silica","abbr":"","def":"용액에서 성장시킨 둥글고 크기가 고른 실리카 입자. 스크래치가 적어 구리·배리어·최종 연마에 쓴다.","chapters":["slurry#abrasive","copper"]},
    {"ko":"세리아","en":"ceria (CeO₂)","abbr":"CeO₂","def":"산화세륨 연마입자. 실리카보다 무르지만 Ce³⁺/Ce⁴⁺ 표면이 Si–O–Ce 결합을 만드는 화학적 치아로 산화막을 빠르게 깎는다. 0.5~1 wt% 저농도로 STI·ILD에 쓰며 질화막 선택비가 높다.","chapters":["slurry#ceria","oxide#ceria"]},
    {"ko":"화학적 치아","en":"chemical tooth","abbr":"","def":"세리아 입자 표면이 산화막과 Ce–O–Si 결합을 만든 뒤 입자가 움직이며 표면 원자를 뜯어내는 메커니즘. 질화막과는 이 결합이 약해 선택비가 생긴다.","chapters":["slurry#ceria","oxide#ceria"]},
    {"ko":"산화제","en":"oxidizer","abbr":"","def":"금속 표면을 산화해 무른 산화물·착물층을 만드는 성분(H₂O₂, Fe(NO₃)₃, KIO₄ 등). 농도가 제거율과 부식을 함께 올리므로 억제제와 균형을 맞춘다.","chapters":["slurry#copper","copper#chem","metals#wchem"]},
    {"ko":"착화제","en":"complexing agent","abbr":"","def":"금속 이온과 수용성 착물을 만들어 산화된 금속을 녹여 나르는 성분(글리신, 시트르산 등). 구리 슬러리의 제거율을 크게 올리지만 정적 식각률도 올린다.","chapters":["slurry#copper","copper#chem","postclean#chem"]},
    {"ko":"부식 방지제","en":"corrosion inhibitor","abbr":"","def":"금속 표면에 흡착하거나 착물 막을 만들어 정적 식각과 부식을 막는 성분. 패드가 누르는 높은 곳에서는 막이 벗겨지고 낮은 곳은 보호되어 평탄화를 돕는다. 구리는 BTA가 대표다.","chapters":["slurry#copper","copper#chem","postclean#chem"]},
    {"ko":"벤조트리아졸","en":"benzotriazole","abbr":"BTA","def":"구리 부식 방지제. Cu(I)와 고분자 착물 막(Cu–BTA)을 만들어 정적 식각을 막고 디싱을 줄인다. CMP 후에는 이 막과 유기 잔류물을 세정으로 지워야 한다.","chapters":["copper#chem","slurry","postclean#chem"]},
    {"ko":"제타 전위","en":"zeta potential","abbr":"ζ","def":"입자와 함께 움직이는 액체층 경계(미끄럼면)의 전위. 크기가 약 30 mV 이상이면 정전 반발로 분산이 안정하다. pH와 염 농도로 바뀌고 입자–웨이퍼 부착에도 결정적이다.","chapters":["slurry#zeta","cleanbasics#zeta"]},
    {"ko":"등전점","en":"IsoElectric Point","abbr":"IEP","def":"제타 전위가 0이 되는 pH. 실리카는 약 pH 2~3, 세리아 약 6~8, 알루미나 약 9, 질화막 약 4~6. IEP 근처에서는 반발이 사라져 응집하고 입자가 표면에 잘 붙는다.","chapters":["slurry#zeta","cleanbasics#zeta","oxide#ceria"]},
    {"ko":"전기 이중층","en":"Electrical Double Layer","abbr":"EDL","def":"대전된 표면과 그 주위에 모인 반대 전하 이온층(고정층 + 확산층). 두 입자의 이중층이 겹치면 정전 반발이 생긴다.","chapters":["slurry#zeta"]},
    {"ko":"디바이 길이","en":"Debye length","abbr":"κ⁻¹","def":"전기 이중층의 두께 척도. 25 °C 1:1 전해질에서 κ⁻¹ ≈ 0.304/√I nm (I: 이온 세기, M). 10 mM에서 약 3 nm, 100 mM에서 약 1 nm로, 염이 많을수록 반발 범위가 짧아져 응집한다.","chapters":["slurry#zeta","slurry#dlvo"]},
    {"ko":"DLVO 이론","en":"Derjaguin–Landau–Verwey–Overbeek theory","abbr":"DLVO","def":"입자 사이 상호작용 에너지를 반데르발스 인력과 이중층 정전 반발의 합으로 보는 이론. 에너지 장벽이 약 15~20 kT 이상이면 분산이 안정하다. 슬러리 안정성과 세정 중 재부착을 함께 설명한다.","chapters":["slurry#dlvo","cleanbasics#zeta"]},
    {"ko":"하마커 상수","en":"Hamaker constant","abbr":"A","def":"두 물체 사이 반데르발스 인력의 세기를 정하는 물질 상수(물 속 산화물 약 10⁻²⁰ J 규모, 진공에서 약 10⁻¹⁹ J). 구–평면 인력 F = A·R/(6z²)에 들어간다.","chapters":["slurry#dlvo","cleanbasics#adhesion"]},
    {"ko":"안정성 비","en":"stability ratio","abbr":"W","def":"장벽이 없을 때의 충돌·응집 속도를 실제 응집 속도로 나눈 값. W ≈ exp(장벽/kT)에 비례해 장벽이 조금만 낮아져도 응집이 급격히 빨라진다.","chapters":["slurry#agglomeration"]},
    {"ko":"응집","en":"agglomeration, aggregation","abbr":"","def":"입자가 서로 붙어 큰 덩어리(응집체)가 되는 현상. pH 충격·염 첨가·건조·과도한 전단·동결이 장벽을 넘게 해 1 µm 안팎의 덩어리를 만들고 스크래치의 주원인이 된다.","chapters":["slurry#agglomeration","defects#causes"]},
    {"ko":"큰 입자 수","en":"Large Particle Count","abbr":"LPC","def":"슬러리 mL당 0.5 µm·1 µm 이상 입자 수. 평균 입경이 같아도 이 꼬리가 마이크로 스크래치 빈도를 정한다. 액중 입자 계수기로 재며 필터 교체 시점의 지표다.","chapters":["slurry#lpc","defects#causes"]},
    {"ko":"마이크로 스크래치","en":"micro-scratch","abbr":"","def":"큰 입자·응집체·탈락 다이아몬드·패드 잔해가 웨이퍼를 긁어 남긴 수십 nm 폭의 긴 흠. 배선 단락·단선을 만드는 대표적인 킬러 결함이다.","chapters":["defects#causes","slurry#lpc","conditioning#pullout"]},
    {"ko":"깊이형 필터","en":"depth filter (POU filter)","abbr":"","def":"두꺼운 섬유층 전체에서 큰 입자를 확률적으로 붙잡는 필터. 슬러리 공급 계통과 사용 지점(POU)에 두어 LPC를 낮춘다. 압력 충격 때 붙잡았던 응집체를 한꺼번에 풀어내는 언로딩을 조심한다.","chapters":["slurry#lpc","defects#prevent"]},
    {"ko":"푸르베 도표","en":"Pourbaix diagram","abbr":"","def":"전위–pH 평면에 금속이 면역(안정한 금속)·부식(이온으로 용해)·부동태(산화물·수산화물 막)인 영역을 그린 도표. 슬러리와 세정액이 금속을 녹일지 보호할지 판단하는 지도다.","chapters":["slurry#copper","metals#newmetals","copper#chem","postclean#chem"]},
    {"ko":"부동태·면역·부식 영역","en":"passivation / immunity / corrosion regions","abbr":"","def":"푸르베 도표의 세 영역. 면역은 금속 자체가 안정, 부식은 이온이 녹아나는 상태, 부동태는 얇은 산화막이 더 녹는 것을 막는 상태다. CMP는 부동태막을 기계적으로 걷어 내는 방식으로 금속을 깎는다.","chapters":["metals#newmetals","slurry#copper"]},
    {"ko":"사용 지점 블렌딩","en":"Point-Of-Use (POU) blending","abbr":"","def":"연마입자 원액과 산화제(H₂O₂ 등)를 장비 바로 앞에서 섞는 방식. 섞은 뒤 분해·응집이 빨리 진행되는 슬러리의 사용 가능 시간 문제를 피한다.","chapters":["slurry#handling"]},
    {"ko":"사용 가능 시간","en":"pot life","abbr":"","def":"산화제를 섞은 슬러리가 성능을 유지하는 시간. H₂O₂ 분해(특히 금속 이온 촉매), pH 변화, 응집으로 제거율이 떨어지므로 블렌딩 시점과 순환 시간을 관리한다.","chapters":["slurry#handling","metals#wchem"]},
    {"ko":"슬러리 공급 계통","en":"Slurry Delivery System","abbr":"SDS","def":"드럼·토트에서 슬러리를 혼합·희석하고 순환 루프로 장비까지 보내는 설비. 침강을 막기 위해 계속 돌리고, 과한 전단·공기 혼입·건조를 피하도록 펌프와 배관을 설계한다.","chapters":["slurry#handling"]},
    {"ko":"마찰 계수","en":"Coefficient Of Friction","abbr":"COF, μ","def":"마찰력을 수직 하중으로 나눈 값. CMP에서 약 0.1~0.6이며 정반·헤드 모터 토크에서 추정한다. 윤활 영역, 막 종류, 패드 상태에 따라 달라져 공정 감시 신호가 된다.","chapters":["tribology#friction","endpoint#torque"]},
    {"ko":"스트리벡 곡선","en":"Stribeck curve","abbr":"","def":"마찰 계수를 허시 수(또는 좀머펠트 수)에 대해 그린 곡선. 경계 윤활(높고 일정) → 부분 윤활(급감) → 유체 윤활(완만히 증가)로 이어진다. CMP는 주로 경계~부분 윤활에서 운전된다.","chapters":["tribology#stribeck"]},
    {"ko":"허시 수","en":"Hersey number","abbr":"H","def":"H = η·V/P (η: 슬러리 점도, V: 속도, P: 압력). 커질수록 유체막이 두꺼워져 접촉이 줄어든다. 스트리벡 곡선의 가로축이다.","chapters":["tribology#stribeck"]},
    {"ko":"좀머펠트 수","en":"Sommerfeld number","abbr":"So","def":"허시 수에 길이 척도를 붙인 무차원 수. CMP 문헌에서는 So = η·V/(P·δ) (δ: 유효 막 두께·패드 거칠기)로 쓰며 윤활 영역을 가르는 기준이다.","chapters":["tribology#stribeck"]},
    {"ko":"경계 윤활","en":"boundary lubrication","abbr":"","def":"하중 대부분을 고체 접촉(패드 돌기–입자–웨이퍼)이 받는 영역. 마찰 계수가 높고 제거율이 프레스턴 식을 잘 따른다.","chapters":["tribology#stribeck"]},
    {"ko":"부분 윤활","en":"mixed (partial) lubrication","abbr":"","def":"하중을 고체 접촉과 유체막이 나눠 받는 영역. 속도를 올리거나 압력을 낮추면 유체 분담이 늘어 마찰 계수와 제거율이 함께 떨어진다.","chapters":["tribology#stribeck","tribology#film"]},
    {"ko":"유체 윤활","en":"hydrodynamic lubrication","abbr":"","def":"유체막이 하중을 모두 떠받쳐 고체가 닿지 않는 영역. 연마가 거의 일어나지 않으므로 CMP에서는 피해야 하는 상태(하이드로플레이닝)다.","chapters":["tribology#stribeck","pad#hydro"]},
    {"ko":"레이놀즈 방정식","en":"Reynolds equation","abbr":"","def":"얇은 유체막의 압력 분포를 주는 윤활 방정식. 막 두께·속도·점도로 슬러리 막이 떠받치는 하중을 계산해 하이드로플레이닝과 하중 분담률을 추정한다.","chapters":["tribology#film","pad#hydro"]},
    {"ko":"마찰 일률 모델","en":"frictional power model","abbr":"","def":"제거율이 마찰 일률에 비례한다고 보는 모델 RR = k·μ·P·V. 프레스턴 계수의 차이 상당 부분을 마찰 계수 차이로 설명한다.","chapters":["tribology#cof-preston","preston"]},
    {"ko":"스틱-슬립","en":"stick-slip","abbr":"","def":"붙었다 미끄러지기를 반복하는 마찰 진동. 정지 마찰이 운동 마찰보다 크거나 속도가 오를수록 마찰이 줄 때(속도 약화) 생기며 채터 마크와 소음의 원인이 된다.","chapters":["tribology#stickslip","defects"]},
    {"ko":"속도 약화","en":"velocity weakening","abbr":"","def":"미끄럼 속도가 오를수록 마찰 계수가 줄어드는 특성(dμ/dV < 0). 계의 감쇠보다 크면 진동이 커져 스틱-슬립이 생긴다.","chapters":["tribology#stickslip"]},
    {"ko":"섬광 온도","en":"flash temperature","abbr":"","def":"접촉점 하나에서 아주 짧은 순간 국소적으로 치솟는 온도. 평균 패드 온도보다 수~수십 °C 높을 수 있어 국소 반응 속도에 영향을 준다.","chapters":["tribology#flash"]},
    {"ko":"페클레 수","en":"Péclet number","abbr":"Pe","def":"열이 움직이는 접촉에 실려 가는 정도와 확산으로 퍼지는 정도의 비 Pe = V·a/(2κ) (a: 접촉 반지름, κ: 열확산율). 크면 열이 접촉 뒤로 남겨져 섬광 온도가 속도의 제곱근에 따라 오른다.","chapters":["tribology#flash"]},
    {"ko":"열수지","en":"heat balance","abbr":"","def":"마찰 발열이 패드·웨이퍼·슬러리·정반으로 나가는 경로를 더한 에너지 균형. 패드 온도는 시상수 수십 초~분으로 정상 상태에 다가간다.","chapters":["tribology#heat"]},
    {"ko":"열 폭주","en":"thermal runaway","abbr":"","def":"온도 상승이 반응 속도와 마찰을 키우고 그것이 다시 발열을 늘리는 되먹임이 냉각보다 강해져 온도가 계속 오르는 상태.","chapters":["tribology#arrhenius"]},
    {"ko":"세묘노프 도표","en":"Semenov diagram","abbr":"","def":"발열 곡선 Q_g(T)과 냉각 직선 Q_l(T) = G(T − T_s)을 함께 그린 그림. 만나는 점이 정상 상태이고, 그 점에서 dQ_g/dT < G이면 안정, 두 선이 만나지 않으면 열 폭주다.","chapters":["tribology#arrhenius"]},
    {"ko":"모터 전류 종점","en":"motor current (torque) endpoint","abbr":"","def":"막이 바뀌어 마찰 계수가 달라질 때 정반·헤드 모터 전류(토크)가 변하는 것을 보고 종점을 잡는 방법. 별도 센서가 필요 없지만 신호 변화가 작고 잡음이 크다.","chapters":["endpoint#torque","tribology#monitor"]},
    {"ko":"고장 감지·분류","en":"Fault Detection and Classification","abbr":"FDC","def":"장비 센서 신호(토크·온도·압력·유량 등)를 실시간 감시해 이상을 감지하고 원인을 분류하는 체계. CMP에서는 마찰 신호가 패드·슬러리 이상의 조기 경보가 된다.","chapters":["tribology#monitor","endpoint"]},
    {"ko":"단차","en":"Step Height","abbr":"SH","def":"패턴 위로 솟은 영역(업)과 내려앉은 영역(다운)의 높이 차. CMP는 업 영역에 압력을 몰아 먼저 깎으며 단차를 줄인다.","chapters":["pattern#topography","pattern#stepheight"]},
    {"ko":"업·다운 영역","en":"up / down area","abbr":"","def":"증착 후 패턴 위로 솟은 높은 영역(업)과 패턴 사이의 낮은 영역(다운). 단차가 크면 하중을 업 영역이 대부분 받는다.","chapters":["pattern#stepheight"]},
    {"ko":"패턴 밀도","en":"pattern density","abbr":"ρ","def":"일정 창 안에서 업 영역(또는 금속)이 차지하는 면적 비율. 업 영역 압력 ≈ P/ρ라 밀도가 낮은 곳은 빨리, 높은 곳은 늦게 깎인다.","chapters":["pattern#stepheight","pattern#density-model"]},
    {"ko":"접촉 높이","en":"contact height","abbr":"","def":"단차가 이 값 아래로 줄면 다운 영역도 패드에 닿아 깎이기 시작하는 높이. 패드 돌기 높이 분포와 강성이 정하며, 그 아래에서는 단차 제거가 느려진다.","chapters":["pattern#stepheight"]},
    {"ko":"평탄화 효율","en":"planarization efficiency","abbr":"PE","def":"업 영역 제거량 대비 단차가 줄어든 정도. PE = 1 − RR_down/RR_up로 쓰며 1에 가까울수록 다운 영역을 덜 깎고 단차만 없앤다.","chapters":["pattern#stepheight","oxide#ceria"]},
    {"ko":"유효 밀도","en":"effective density","abbr":"ρ_eff","def":"패턴 밀도를 평탄화 길이 크기의 가중 함수로 평균한 값. 칩 위 한 점의 국소 압력과 제거율은 국소 밀도가 아니라 유효 밀도가 정한다.","chapters":["pattern#density-model"]},
    {"ko":"가중 함수","en":"weighting function, kernel","abbr":"","def":"유효 밀도를 구할 때 주변 밀도에 거리별로 주는 가중치(타원·가우스형). 폭이 평탄화 길이다.","chapters":["pattern#density-model"]},
    {"ko":"스타인·오우마 밀도 모델","en":"Stine–Ouma pattern density model","abbr":"","def":"업 영역 제거율 = 블랭킷 제거율/유효 밀도로 두고 단차가 접촉 높이 아래로 내려가면 업·다운을 함께 깎는다고 보는 MIT 계열 칩 규모 CMP 모델. DFM 시뮬레이션의 기초다.","chapters":["pattern#density-model"]},
    {"ko":"다이 내 불균일","en":"Within-Die Non-Uniformity","abbr":"WIDNU","def":"다이 안의 막 두께(또는 높이) 산포. 레이아웃 밀도 차이에서 오며 웨이퍼 규모 균일도(WIWNU)와 구별해 관리한다.","chapters":["pattern#density-model"]},
    {"ko":"오버폴리시","en":"over-polish","abbr":"","def":"종점 이후 잔류물을 확실히 없애려고 더 연마하는 것. 웨이퍼 안 클리어 시간 산포를 덮지만 디싱·이로전·정지막 손실을 키우는 대가가 있다.","chapters":["pattern#dishing","copper#overpolish","oxide#overpolish","endpoint"]},
    {"ko":"더미 필","en":"dummy fill","abbr":"","def":"회로 기능이 없는 금속·활성 영역 조각을 빈 곳에 채워 패턴 밀도를 고르게 하는 것. 이로전·WIDNU를 줄이지만 기생 용량을 늘리므로 이격 거리를 둔다.","chapters":["pattern#dummyfill"]},
    {"ko":"슬로팅","en":"slotting, cheesing","abbr":"","def":"넓은 금속 판에 구멍을 뚫어 국소 밀도를 낮추는 것. 넓은 배선의 디싱을 줄인다.","chapters":["pattern#dummyfill"]},
    {"ko":"밀도 규칙","en":"density rule (min / max, window)","abbr":"","def":"정해진 창(예: 수십~수백 µm) 안의 패턴 밀도가 최소·최대 한계와 인접 창 간 변화 한계를 넘지 않게 하는 레이아웃 규칙. 더미 필과 슬로팅으로 맞춘다.","chapters":["pattern#dummyfill"]},
    {"ko":"이격 거리","en":"keep-off distance","abbr":"","def":"더미 필을 실제 배선에서 떨어뜨려 놓는 최소 거리. 결합 용량과 신호 지연을 줄이기 위해 둔다.","chapters":["pattern#dummyfill"]},
    {"ko":"제조성 고려 설계","en":"Design For Manufacturability","abbr":"DFM","def":"설계 단계에서 공정 변동(CMP 두께·리소 핫스팟 등)을 모델로 예측해 레이아웃을 고치는 방법. CMP 모델로 두께 지도를 계산해 핫스팟을 찾는다.","chapters":["pattern#dfm"]},
    {"ko":"핫스팟","en":"hotspot","abbr":"","def":"공정 모델이 디싱·이로전·잔류물·단차가 한계를 넘을 것으로 예측한 레이아웃 위치. 더미 필·슬로팅·설계 변경으로 없앤다.","chapters":["pattern#dfm"]},
    {"ko":"층간 절연막","en":"Inter-Layer Dielectric","abbr":"ILD","def":"배선층 사이 산화막. 증착 후 CMP로 평탄화해 다음 리소의 DOF 예산을 지킨다. 산화막 CMP의 대표 대상이다.","chapters":["oxide#ild","overview"]},
    {"ko":"금속 전 절연막","en":"Pre-Metal Dielectric","abbr":"PMD","def":"트랜지스터와 첫 금속 배선 사이의 절연막(보통 BPSG·산화막). 게이트 단차 위에 증착되어 CMP로 평탄화한다.","chapters":["oxide#ild","overview"]},
    {"ko":"금속 간 절연막","en":"Inter-Metal Dielectric","abbr":"IMD","def":"금속 배선층 사이의 절연막. 구리 배선에서는 저유전막이 쓰이며 다마신 패턴의 바탕이 된다.","chapters":["oxide#ild","copper#lowk"]},
    {"ko":"수화층 모델","en":"hydrated layer model","abbr":"","def":"실리카 슬러리의 높은 pH와 물이 산화막 표면 Si–O–Si 결합을 끊어 무른 수화층(Si–OH)을 만들고, 입자가 이 층을 걷어 낸다는 산화막 CMP 모델. pH 10~11에서 제거율이 크다.","chapters":["oxide#hydration","preston#chemistry"]},
    {"ko":"얕은 트렌치 소자 분리","en":"Shallow Trench Isolation","abbr":"STI","def":"실리콘에 얕은 홈을 파고 산화막으로 채워 트랜지스터를 분리하는 구조. 넘친 산화막을 CMP로 깎아 질화막에서 멈춘 뒤 질화막을 벗긴다.","chapters":["oxide#sti","overview"]},
    {"ko":"패드 산화막·패드 질화막","en":"pad oxide / pad nitride","abbr":"","def":"STI 식각 전에 실리콘 위에 차례로 올리는 얇은 산화막(응력 완충)과 질화막(CMP 정지막·식각 마스크). CMP 후 인산으로 질화막을 벗긴다.","chapters":["oxide#sti"]},
    {"ko":"정지막","en":"stop layer","abbr":"","def":"CMP가 그 위에서 멈추도록 깎이는 속도가 훨씬 느린 막. STI의 질화막, 구리 CMP의 배리어·캡, SAC의 질화막 캡 등.","chapters":["oxide#sti","overview","metals#selectivity"]},
    {"ko":"갭필","en":"gap fill (HDP-CVD, HARP)","abbr":"","def":"트렌치·배선 사이를 빈틈없이 채우는 증착. HDP-CVD는 증착·스퍼터 식각을 겹쳐 메우고, HARP 같은 열 CVD는 컨포멀하게 채운다. 방식에 따라 CMP 전 단차 모양이 달라진다.","chapters":["oxide#sti"]},
    {"ko":"음이온성 첨가제","en":"anionic additive (PAA)","abbr":"","def":"폴리아크릴산 같은 음이온성 고분자. 세리아 STI 슬러리에서 양전하를 띤 질화막 표면에 흡착해 보호막을 만들고 질화막 제거율을 크게 낮춘다.","chapters":["oxide#ceria"]},
    {"ko":"선택비","en":"selectivity","abbr":"","def":"두 막의 제거율 비(예: 산화막/질화막). 세리아 STI 슬러리는 수십~수백, 구리 P2는 Cu/배리어가 크다. 오버폴리시 동안 정지막 손실 = 오버폴리시 시간 × 정지막 제거율.","chapters":["oxide#overpolish","overview","metals#selectivity","copper#steps"]},
    {"ko":"자기 정지","en":"self-stopping","abbr":"","def":"단차가 사라져 다운 영역 압력이 문턱 아래로 떨어지거나 질화막이 드러나면 제거율이 저절로 크게 줄어드는 현상. 세리아+첨가제 슬러리와 고정 연마입자의 특징이다.","chapters":["oxide#ceria"]},
    {"ko":"잔류 산화막","en":"oxide residue","abbr":"","def":"질화막 위에 다 지워지지 않고 남은 산화막. 이후 질화막 제거를 막아 소자 결함이 되므로 오버폴리시로 지운다.","chapters":["oxide#overpolish"]},
    {"ko":"질화막 손실","en":"nitride loss","abbr":"","def":"CMP 중 정지막인 질화막이 깎인 두께. 넓은 질화막 영역과 좁은 영역에서 다르며 최종 필드 산화막 높이 산포의 원인이 된다.","chapters":["oxide#overpolish"]},
    {"ko":"필드 산화막 높이","en":"Field Oxide Height","abbr":"FOH","def":"STI 산화막 윗면이 활성 실리콘 표면보다 솟은 높이. 게이트 형성의 단차를 정하므로 수 nm 범위로 관리한다.","chapters":["oxide#foh"]},
    {"ko":"디봇","en":"divot","abbr":"","def":"STI 산화막 모서리가 HF 습식 처리로 패여 생기는 홈. 게이트가 모서리를 감싸며 기생 트랜지스터·누설을 만든다.","chapters":["oxide#foh"]},
    {"ko":"고정 연마입자","en":"fixed abrasive","abbr":"","def":"연마입자를 패드 안에 고정하고 입자 없는 용액으로 연마하는 방식. 단차가 사라지면 제거율이 급감하는 자기 정지 특성이 강하고 디싱이 적다.","chapters":["oxide#fixed"]},
    {"ko":"종점 검출","en":"EndPoint Detection","abbr":"EPD","def":"막이 바뀌거나 목표 두께에 이른 순간을 연마 중 센서(모터 토크·광학·와전류·음향 등)로 알아내 연마를 멈추는 것. 시간 연마의 산포를 줄인다.","chapters":["endpoint#methods","oxide#endpoint","copper#steps"]},
    {"ko":"다마신","en":"damascene","abbr":"","def":"절연막에 홈을 먼저 파고 금속을 채운 뒤 CMP로 넘친 금속을 걷어 배선을 만드는 상감 공정. 구리는 건식 식각이 어려워 이 방법을 쓴다.","chapters":["copper#why","overview"]},
    {"ko":"듀얼 다마신","en":"dual damascene","abbr":"","def":"비아와 배선 홈을 함께 파고 한 번의 배리어·시드·도금·CMP로 동시에 채우는 다마신. 공정 단계와 계면 수가 줄어든다.","chapters":["copper#flow"]},
    {"ko":"감산 공정","en":"subtractive patterning","abbr":"","def":"금속막을 먼저 깔고 식각해 배선을 남기는 전통 방식(알루미늄). 초미세 피치에서 Ru·Mo 같은 금속으로 다시 검토되고 있다.","chapters":["copper#why"]},
    {"ko":"확산 배리어","en":"diffusion barrier (Ta/TaN)","abbr":"","def":"구리가 절연막으로 확산되는 것을 막고 접착을 돕는 수 nm의 TaN/Ta 층. 구리 CMP의 P3 단계에서 제거한다.","chapters":["copper#flow","copper#steps"]},
    {"ko":"시드층","en":"seed layer","abbr":"","def":"전해 도금이 시작되도록 배리어 위에 PVD로 얇게 입힌 구리층. 좁은 홈 측벽에서 끊기지 않게 덮는 것이 미세화의 난제다.","chapters":["copper#flow"]},
    {"ko":"전해 도금","en":"ElectroChemical Deposition","abbr":"ECD","def":"전류로 용액 속 구리 이온을 환원해 시드층 위에 구리를 채우는 공정. 첨가제로 바닥부터 차오르게 한다.","chapters":["copper#ecd"]},
    {"ko":"슈퍼필","en":"superfill (bottom-up fill)","abbr":"","def":"가속제·억제제·평탄제 첨가제의 작용으로 좁은 홈 바닥이 먼저 빨리 차오르는 도금. 빈틈 없이 채우지만 미세 패턴 위에 볼록한 범프를 만든다.","chapters":["copper#ecd"]},
    {"ko":"도금 범프·딥","en":"plating bump / dip","abbr":"","def":"슈퍼필 뒤 미세 패턴 밀집부 위에 생긴 볼록한 과충전(범프)과 넓은 배선 위의 오목함(딥). CMP가 걷어야 할 초기 단차가 된다.","chapters":["copper#ecd"]},
    {"ko":"오버버든","en":"overburden","abbr":"","def":"다마신 홈 위 필드에 쌓인 남는 금속. CMP P1이 대부분을 걷어 내며, 두께와 범프 단차가 CMP 시간을 정한다.","chapters":["copper#ecd","copper#steps","metals#wplug"]},
    {"ko":"3단계 구리 CMP","en":"P1 bulk / P2 clear / P3 barrier","abbr":"P1–P3","def":"P1은 높은 압력·제거율로 벌크 구리를 걷고, P2는 낮은 압력으로 남은 구리를 배리어까지 클리어(종점 검출)하며, P3는 배리어와 약간의 절연막을 깎아 디싱을 보정한다. CP-300 압력은 2·1.2·1.5 psi.","chapters":["copper#steps"]},
    {"ko":"혼성 전위","en":"mixed potential","abbr":"E_corr","def":"금속 산화(양극) 전류와 산화제 환원(음극) 전류가 같아지는 표면 전위(부식 전위). 이 점의 전류가 부식 전류이며, 두 금속이 맞닿으면 혼성 전위 차이가 갈바닉 부식의 구동력이 된다.","chapters":["copper#echem","metals#newmetals"]},
    {"ko":"부식 전류","en":"corrosion current density","abbr":"i_corr","def":"혼성 전위에서 흐르는 양극 전류 밀도. 패러데이 법칙으로 용해 속도(정적 식각률)로 바뀐다. 억제제는 i_corr를 크게 낮춘다.","chapters":["copper#echem"]},
    {"ko":"에반스 다이어그램","en":"Evans diagram","abbr":"","def":"양극·음극 반응의 전위 대 log 전류를 겹쳐 그려 교점으로 혼성 전위와 부식 전류를 읽는 그림.","chapters":["copper#echem"]},
    {"ko":"갈바닉 부식","en":"galvanic corrosion","abbr":"","def":"서로 다른 금속(Cu–Ta, Cu–Co, W–Ti 등)이 전해질 속에서 닿을 때 전위가 낮은 쪽이 양극이 되어 빨리 녹는 현상. CMP 클리어 직후와 세정 중에 생긴다.","chapters":["copper#galvanic","postclean#chem","defects#corrosion","metals#newmetals"]},
    {"ko":"광부식","en":"photo-corrosion","abbr":"","def":"빛이 p–n 접합에 전자–정공 쌍을 만들어 접합에 연결된 구리 배선이 녹거나 석출되는 현상. 세정·건조 중 조명을 낮추거나 차광해서 막는다.","chapters":["copper#galvanic","postclean","defects#corrosion"]},
    {"ko":"저유전막","en":"low-k dielectric","abbr":"low-k","def":"유전율이 SiO₂(약 3.9)보다 낮은 절연막(SiCOH, 다공성 막). 배선 용량을 줄이지만 탄성률·접착력이 약해 고압 CMP에서 박리·균열이 생기고 수분·약액에 손상된다.","chapters":["copper#lowk","defects"]},
    {"ko":"박리","en":"delamination","abbr":"","def":"막과 막 사이가 떨어지는 결함. 연마 전단력이 약한 저유전막 계면의 접착 에너지를 넘을 때 생긴다. 저압·저마찰 연마로 막는다.","chapters":["copper#lowk","defects"]},
    {"ko":"대기 시간","en":"queue time","abbr":"Q-time","def":"한 공정이 끝난 뒤 다음 공정을 시작해야 하는 최대 허용 시간. CMP 후 세정까지, 세정 후 캡 증착까지 구리 표면이 부식·산화되기 전에 넘어가도록 정한다.","chapters":["postclean#qtime","copper","defects#corrosion","overview"]},
    {"ko":"콘택 플러그","en":"contact plug","abbr":"","def":"트랜지스터 소스·드레인·게이트와 첫 배선을 잇는 세로 금속 기둥. 주로 W를 CVD로 채우고 CMP로 위를 걷어 만든다.","chapters":["metals#wplug"]},
    {"ko":"라이너","en":"liner (Ti/TiN)","abbr":"","def":"W 플러그 아래 접착층 Ti와 확산 방지층 TiN. W CMP에서 W와 함께 걷어야 하며 W와 갈바닉 쌍을 이룬다.","chapters":["metals#wplug"]},
    {"ko":"심","en":"seam","abbr":"","def":"컨포멀 CVD가 홈 양쪽 벽에서 자라 가운데에서 만나며 남긴 이음선. CMP 중 드러나면 슬러리가 들어가 부식·리세스를 키운다.","chapters":["metals#wplug","metals#recess"]},
    {"ko":"키홀","en":"keyhole","abbr":"","def":"홈 입구가 먼저 막혀 플러그 안에 남은 빈 공간. CMP로 위가 깎여 열리면 슬러리·세정액이 갇혀 결함이 된다.","chapters":["metals#wplug","metals#recess"]},
    {"ko":"플러그 리세스","en":"plug recess","abbr":"","def":"W 플러그 윗면이 주변 절연막보다 낮게 깎인 깊이. 화학 식각과 오버폴리시가 키우며 다음 층 접촉 저항을 올린다.","chapters":["metals#recess"]},
    {"ko":"펜톤 반응","en":"Fenton reaction","abbr":"","def":"Fe²⁺ + H₂O₂ → Fe³⁺ + OH· + OH⁻. 철 촉매가 과산화수소에서 강한 OH 라디칼을 만들어 W를 무른 WO₃로 산화한다. W 슬러리의 핵심 화학이다.","chapters":["metals#wchem"]},
    {"ko":"대체 금속 게이트","en":"Replacement Metal Gate","abbr":"RMG","def":"더미 폴리 게이트로 소자를 만든 뒤 고온 공정이 끝나면 폴리를 빼고 고유전막·금속 게이트로 바꾸는 방식. 두 번의 CMP(POP, 금속 게이트 CMP)가 게이트 높이를 정한다.","chapters":["metals#rmg","overview"]},
    {"ko":"고유전·금속 게이트","en":"High-k / Metal Gate","abbr":"HKMG","def":"SiO₂ 대신 HfO₂ 같은 고유전막과 금속 게이트를 쓰는 트랜지스터 게이트 구조. 대개 RMG로 만든다.","chapters":["metals#rmg"]},
    {"ko":"폴리 개방 연마","en":"Poly Open Polish","abbr":"POP","def":"RMG에서 더미 폴리 게이트 위의 절연막을 깎아 폴리 윗면을 드러내는 CMP. 게이트 높이 예산의 첫 소비 단계다.","chapters":["metals#rmg"]},
    {"ko":"자기 정렬 콘택","en":"Self-Aligned Contact","abbr":"SAC","def":"게이트 위에 질화막 캡을 씌워 콘택이 게이트에 조금 어긋나도 단락되지 않게 하는 구조. 캡 형성에 CMP가 쓰인다.","chapters":["metals#rmg"]},
    {"ko":"일함수 금속","en":"Work-Function metal","abbr":"WFM","def":"트랜지스터 문턱 전압을 정하는 게이트 금속층(TiN·TiAl 등). 금속 게이트 CMP에서 여러 금속을 함께 깎아야 해 선택비 설계가 어렵다.","chapters":["metals#rmg"]},
    {"ko":"폴리실리콘 CMP","en":"polysilicon CMP","abbr":"","def":"다결정 실리콘을 깎는 CMP. 알칼리 슬러리로 빠르게 깎이며 산화막·질화막 정지 선택비를 이용한다.","chapters":["metals#poly"]},
    {"ko":"코발트","en":"cobalt (Co)","abbr":"Co","def":"미세 콘택·배선과 라이너에 쓰는 금속. 짧은 평균 자유 행로로 좁은 선에서 저항이 유리하지만 쉽게 부식되고 Cu와 갈바닉 쌍을 이룬다.","chapters":["metals#newmetals"]},
    {"ko":"루테늄","en":"ruthenium (Ru)","abbr":"Ru","def":"배리어 없이 쓸 수 있는 차세대 배선 금속 후보. 화학적으로 매우 안정해 깎기 어렵고, 강한 산화제로 산화하면 휘발성·독성 RuO₄가 생길 수 있다.","chapters":["metals#newmetals"]},
    {"ko":"사산화루테늄","en":"ruthenium tetroxide","abbr":"RuO₄","def":"Ru을 강하게 산화할 때 생기는 휘발성·독성 산화물. 슬러리 pH와 산화제 선택으로 생성을 억제한다.","chapters":["metals#newmetals"]},
    {"ko":"과요오드산칼륨","en":"potassium periodate","abbr":"KIO₄","def":"Ru 슬러리에 쓰는 강한 산화제. Ru을 무른 산화물로 바꾸지만 조건에 따라 RuO₄ 생성 위험이 있다.","chapters":["metals#newmetals"]},
    {"ko":"몰리브덴","en":"molybdenum (Mo)","abbr":"Mo","def":"배리어 없는 미세 배선·워드라인 금속 후보. 알칼리에서 MoO₄²⁻로 쉽게 녹아 부식·리세스 관리가 핵심이다.","chapters":["metals#newmetals"]},
    {"ko":"3D NAND 스테어케이스","en":"staircase (3D NAND)","abbr":"","def":"수백 층 적층 셀 어레이 옆에서 워드 라인을 한 층씩 끌어내는 계단 구조. 어레이와 주변 회로 사이에 수 µm 단차를 만든다.","chapters":["metals#thick"]},
    {"ko":"후막 CMP","en":"thick-film CMP","abbr":"","def":"3D NAND처럼 수 µm 단차 위 두꺼운 산화막을 평탄화하는 CMP. 일반 ILD보다 열 배 이상 깎으며 긴 평탄화 길이와 페리 손실 관리가 성패를 가른다.","chapters":["metals#thick","pattern"]},
    {"ko":"역마스크 에치백","en":"reverse-mask etch-back","abbr":"","def":"높은 영역만 열린 마스크로 미리 식각해 단차를 줄인 뒤 CMP하는 방법. 후막 CMP 부담과 페리 손실을 줄인다.","chapters":["metals#thick"]},
    {"ko":"시간 연마","en":"timed polish","abbr":"","def":"정해진 시간만큼 연마하는 방식. 들어온 두께와 제거율이 변하면 그 산포가 그대로 잔막 산포가 된다.","chapters":["endpoint#why"]},
    {"ko":"들어온 두께","en":"incoming thickness","abbr":"","def":"CMP 직전 막 두께. 증착 산포가 크면 피드포워드로 연마 시간이나 목표를 바꿔 보정한다.","chapters":["endpoint#why","endpoint#apc"]},
    {"ko":"제거율 표류","en":"removal rate drift","abbr":"","def":"패드·디스크·슬러리 상태 변화로 제거율이 웨이퍼마다 서서히 바뀌는 것. 런투런 제어로 추적한다.","chapters":["endpoint#why","endpoint#apc"]},
    {"ko":"인시투 광학 측정","en":"in-situ spectral reflectometry","abbr":"","def":"정반 창을 통해 연마 중인 웨이퍼에 빛을 비추고 반사 스펙트럼을 읽어 투명막 두께를 실시간으로 추정하는 방법. 산화막·STI 종점에 쓴다.","chapters":["endpoint#optical"]},
    {"ko":"박막 간섭","en":"thin-film interference","abbr":"","def":"막 윗면과 아랫면 반사광이 겹쳐 생기는 간섭. 수직 입사에서 두께가 λ/(2n) 바뀔 때마다 반사율이 한 주기 진동한다(λ = 600 nm, 산화막 n = 1.46이면 약 205 nm).","chapters":["endpoint#optical"]},
    {"ko":"에어리 식","en":"Airy formula","abbr":"","def":"얇은 막의 반사 계수 r = (r₀₁ + r₁₂e^(−2iβ))/(1 + r₀₁r₁₂e^(−2iβ)), β = 2πn d cosθ/λ. 측정 스펙트럼을 이 식에 맞춰 두께를 구한다.","chapters":["endpoint#optical"]},
    {"ko":"스펙트럼 라이브러리","en":"spectral library fitting","abbr":"","def":"두께별로 미리 계산하거나 측정한 반사 스펙트럼 모음과 측정 스펙트럼을 비교해 가장 잘 맞는 두께를 고르는 방법. 아래층 패턴 효과를 담을 수 있다.","chapters":["endpoint#optical"]},
    {"ko":"와전류 센서","en":"eddy current sensor","abbr":"","def":"코일의 교류 자기장이 금속막에 유도한 와전류로 면저항(두께)을 재는 센서. 구리 벌크 두께와 클리어 종점에 쓴다.","chapters":["endpoint#eddy","copper#steps"]},
    {"ko":"표피 깊이","en":"skin depth","abbr":"δ","def":"교류 전자기장이 도체 속으로 들어가는 깊이 δ = 1/√(πfμσ). 구리(σ = 5.8×10⁷ S/m)에서 1 MHz일 때 약 66 µm라 수 µm 이하 막에서는 와전류 신호가 두께에 비례한다.","chapters":["endpoint#eddy"]},
    {"ko":"리프트오프","en":"lift-off (sensor gap)","abbr":"","def":"와전류 센서와 금속막 사이 거리. 패드가 닳으면 거리가 줄어 신호가 바뀌므로 두께 신호와 분리해 보정해야 한다.","chapters":["endpoint#eddy"]},
    {"ko":"음향 방출","en":"Acoustic Emission","abbr":"AE","def":"연마 중 접촉·마찰에서 나오는 고주파 탄성파. 막 전환·스크래치·이상 접촉을 감지하는 보조 센서로 쓴다.","chapters":["endpoint#thermal"]},
    {"ko":"홀드오프","en":"hold-off","abbr":"","def":"연마 시작 직후 일정 시간 종점 판정을 하지 않는 구간. 초기 과도 신호로 잘못 멈추는 것을 막는다.","chapters":["endpoint#torque"]},
    {"ko":"통합 계측","en":"Integrated Metrology","abbr":"IM","def":"CMP 장비 안에 붙은 두께 측정기. 연마 직후 웨이퍼를 재서 런투런 제어에 바로 피드백한다.","chapters":["endpoint#apc"]},
    {"ko":"런투런 제어","en":"Run-to-Run control","abbr":"R2R","def":"앞 웨이퍼(로트)의 측정 결과로 다음 웨이퍼의 레시피(시간·압력)를 고치는 제어. 제거율 표류와 들어온 두께 산포를 줄인다.","chapters":["endpoint#apc","advanced#vm"]},
    {"ko":"지수 가중 이동 평균","en":"Exponentially Weighted Moving Average","abbr":"EWMA","def":"추정값을 ŷₜ = λyₜ + (1 − λ)ŷₜ₋₁로 갱신하는 필터. λ가 크면 빨리 따라가지만 잡음에 민감하다. R2R 제어기의 표준이다.","chapters":["endpoint#apc"]},
    {"ko":"피드포워드·피드백","en":"feedforward / feedback","abbr":"","def":"피드포워드는 들어오는 웨이퍼 정보(들어온 두께)로 미리 보정하고, 피드백은 결과 오차로 다음을 보정한다. 둘을 함께 쓴다.","chapters":["endpoint#apc"]},
    {"ko":"첨단 공정 제어","en":"Advanced Process Control","abbr":"APC","def":"R2R 제어·FDC·가상 계측·통합 계측을 묶어 공정 결과를 목표에 붙잡아 두는 공정 제어 체계. CMP에서는 종점 검출과 다중 구역 프로파일 제어까지 포함한다.","chapters":["endpoint#apc","advanced#vm"]},
    {"ko":"채터 마크","en":"chatter mark","abbr":"","def":"일정한 간격으로 반복되는 짧은 긁힘 자국. 스틱-슬립 진동이나 입자가 튀며 긁을 때 생기며, 간격 × 진동 주파수가 미끄럼 속도와 맞는지로 원인을 확인한다.","chapters":["defects#taxonomy","tribology#stickslip"]},
    {"ko":"응집체","en":"agglomerate","abbr":"","def":"연마입자가 뭉친 1 µm 안팎의 덩어리. 건조된 슬러리 껍질, pH 충격, 필터 언로딩이 원인이며 스크래치의 주범이다.","chapters":["defects#causes","slurry#agglomeration"]},
    {"ko":"패드 잔해","en":"pad debris","abbr":"","def":"컨디셔닝과 마모로 떨어진 패드 조각과 굳은 슬러리 껍질. 웨이퍼에 붙어 잔류 결함이 되거나 패드–웨이퍼 사이에 끼어 스크래치를 만든다.","chapters":["defects#taxonomy","conditioning"]},
    {"ko":"잔류 입자","en":"residual particle","abbr":"","def":"CMP·세정 후 웨이퍼에 남은 연마입자·잔해. 세리아는 산화막에 화학 결합해 특히 지우기 어렵다.","chapters":["defects#taxonomy","postclean"]},
    {"ko":"부식 피트","en":"corrosion pit","abbr":"","def":"금속 표면이 국부적으로 깊게 녹아 생긴 구멍. 염화물·갈바닉·Q-time 초과가 원인이다.","chapters":["defects#corrosion","copper#defects"]},
    {"ko":"물반점","en":"watermark","abbr":"","def":"물방울이 마를 때 녹아 있던 실리카·산화물이 남긴 자국. 소수성 표면(HF 후)과 느린 건조에서 잘 생긴다. 마랑고니 건조로 막는다.","chapters":["postclean#dry","defects","wetclean#drying"]},
    {"ko":"명시야·암시야 검사","en":"brightfield / darkfield inspection","abbr":"BF/DF","def":"명시야는 정반사 이미지로 패턴 결함을 고해상도로, 암시야는 비스듬히 비춘 빛의 산란으로 입자·스크래치를 빠르게 찾는다. CMP 후 검사는 암시야가 주력이다.","chapters":["defects#inspect"]},
    {"ko":"헤이즈","en":"haze","abbr":"","def":"표면 거칠기에서 오는 넓게 퍼진 배경 산란. 검사 감도를 낮추며 과식각·거친 세정 같은 표면 상태 지표로도 쓴다.","chapters":["defects#inspect"]},
    {"ko":"레일리 산란","en":"Rayleigh scattering","abbr":"","def":"파장보다 아주 작은 입자의 산란. 세기가 d⁶/λ⁴에 비례해 입자 크기가 절반이면 신호가 1/64로 줄어든다. 작은 결함 검출이 어려운 이유다.","chapters":["defects#inspect"]},
    {"ko":"리뷰 SEM","en":"defect review SEM","abbr":"","def":"검사기가 찾은 결함 좌표를 전자현미경으로 다시 찍어 크기·모양·종류를 확인하는 장비. 광학 검사로는 결함 종류를 알 수 없어 일부를 샘플링해 리뷰한다.","chapters":["defects#inspect"]},
    {"ko":"자동 결함 분류","en":"Automatic Defect Classification","abbr":"ADC","def":"리뷰 이미지를 규칙·머신러닝으로 스크래치·입자·잔류물·부식 등 종류별로 자동 분류하는 것. 결함 파레토와 원인 추적의 입력이 된다.","chapters":["defects#inspect"]},
    {"ko":"결함 지도","en":"defect map, spatial signature","abbr":"","def":"웨이퍼 위 결함 위치의 분포. 활 모양 스크래치(컨디셔너), 가장자리 고리(세정·건조), 방사형(스핀) 같은 공간 서명이 원인을 가리킨다.","chapters":["defects#maps"]},
    {"ko":"임계 면적","en":"critical area","abbr":"A_c","def":"결함 중심이 그 안에 떨어지면 단락·단선이 되는 면적. 결함 지름이 배선 간격을 넘으면서 급히 커지며, 평균 결함 밀도와 곱해 예상 킬러 결함 수를 얻는다.","chapters":["defects#yield"]},
    {"ko":"킬러 결함","en":"killer defect, kill ratio","abbr":"","def":"칩 기능을 망가뜨리는 결함. 검출된 결함 중 실제로 칩을 죽이는 비율을 킬 비율이라 하며, 결함 크기와 임계 면적이 정한다.","chapters":["defects#yield"]},
    {"ko":"음이항 수율 모델","en":"negative binomial yield model","abbr":"","def":"Y = (1 + A·D/α)^(−α). 결함이 뭉치는 정도를 α로 담아 푸아송 모델 e^(−AD)보다 수율을 높게 예측한다.","chapters":["defects#yield"]},
    {"ko":"클러스터 인자","en":"clustering factor","abbr":"α","def":"음이항 모델의 결함 뭉침 정도. 작을수록 결함이 몰려 같은 평균 밀도에서 수율이 높다. α → ∞이면 푸아송.","chapters":["defects#yield"]},
    {"ko":"파레토 차트","en":"Pareto chart","abbr":"","def":"결함 종류를 빈도순 막대로 그려 소수 원인이 대부분을 차지함을 보이는 그림. 개선 우선순위를 정한다.","chapters":["defects#prevent"]},
    {"ko":"입자 오염","en":"particle contamination","abbr":"","def":"웨이퍼 위 고체 입자. 패턴을 가려 단락·단선을 만들고 막 아래 갇히면 박리·돌기를 만든다. 크기가 배선 간격의 절반 이상이면 킬러 결함이 되기 쉽다.","chapters":["cleanbasics#contaminants"]},
    {"ko":"금속 오염","en":"metallic contamination","abbr":"","def":"Fe·Cu·Ni·Na 등 금속 원자의 표면 오염. 10¹⁰ atoms/cm² 수준에서도 산화막 신뢰성과 캐리어 수명을 떨어뜨린다.","chapters":["cleanbasics#contaminants","cleanbasics#impact"]},
    {"ko":"유기 오염","en":"organic contamination","abbr":"","def":"레지스트 잔류물·BTA·공기 중 유기물. 표면을 소수성으로 만들고 막 접착과 산화를 방해한다.","chapters":["cleanbasics#contaminants"]},
    {"ko":"자연 산화막","en":"native oxide","abbr":"","def":"공기·물·산화성 약액 때문에 실리콘 위에 저절로 자라는 약 1 nm 산화막. 접촉 저항과 에피 성장을 방해하므로 HF로 지우고 Q-time으로 재성장을 제한한다.","chapters":["cleanbasics#contaminants","wetclean#dry"]},
    {"ko":"분자 오염","en":"Airborne Molecular Contamination","abbr":"AMC","def":"공기 중 가스 상태 오염(산·염기·응축성 유기물·도펀트). 입자 필터로 걸러지지 않고 대기 중 표면에 흡착해 부식·접착 불량·헤이즈를 만든다.","chapters":["cleanbasics#contaminants"]},
    {"ko":"게이트 산화막 신뢰성","en":"Gate Oxide Integrity","abbr":"GOI","def":"게이트 산화막이 정해진 전계·시간을 견디는 능력. Fe·Cu 같은 금속 오염이 산화막·계면에 결함을 만들어 절연 파괴 전압과 수명을 떨어뜨린다.","chapters":["cleanbasics#impact"]},
    {"ko":"소수 캐리어 수명","en":"minority-carrier lifetime","abbr":"τ","def":"실리콘 속 소수 캐리어가 재결합하기까지의 평균 시간. SRH 식 τ = 1/(σ·v_th·N_t)로 금속 트랩 농도 N_t에 반비례한다.","chapters":["cleanbasics#impact"]},
    {"ko":"가동 이온","en":"mobile ion","abbr":"","def":"Na⁺·K⁺처럼 산화막 속을 움직이는 이온. 문턱 전압을 흔들어 소자 불안정을 만든다.","chapters":["cleanbasics#impact"]},
    {"ko":"반데르발스 힘","en":"van der Waals force","abbr":"","def":"입자–표면 사이 근거리 인력 F = A·R/(6z²) (z ≈ 0.4 nm). R = 50 nm 입자에 수 nN으로 입자 무게보다 수억 배 크다.","chapters":["cleanbasics#adhesion"]},
    {"ko":"모세관력","en":"capillary force","abbr":"","def":"입자와 표면 사이 액체 다리의 표면장력이 끌어당기는 힘 F ≈ 4πγR·cosθ. 습도가 높거나 건조 직전 커져 마른 입자가 젖은 입자보다 단단히 붙는다.","chapters":["cleanbasics#adhesion"]},
    {"ko":"경계층","en":"boundary layer","abbr":"","def":"표면 근처에서 유속이 거의 0으로 줄어드는 층. 평판 층류에서 두께 δ ≈ 5√(νx/U)로 수십~수백 µm라, 그보다 훨씬 작은 입자는 흐름 항력을 거의 받지 못해 헹굼만으로 잘 떨어지지 않는다.","chapters":["cleanbasics#removal","postclean#megasonic"]},
    {"ko":"제거비","en":"removal ratio (moment ratio)","abbr":"","def":"제거력(항력·굴림 모멘트)을 부착력(모멘트)으로 나눈 값. 1보다 커야 입자가 굴러 떨어진다.","chapters":["cleanbasics#removal"]},
    {"ko":"입자 제거 효율","en":"Particle Removal Efficiency","abbr":"PRE","def":"PRE = (세정 전 입자 수 − 세정 후 입자 수)/세정 전 입자 수. 일부러 입자를 뿌린 시편으로 잰다.","chapters":["cleanbasics#removal","postclean"]},
    {"ko":"RCA 세정","en":"RCA clean","abbr":"","def":"1970년 Kern이 제안한 표준 습식 세정. SC1으로 입자·유기물을, SC2로 금속을 지우며 HF를 사이에 넣는다.","chapters":["cleanbasics#rca"]},
    {"ko":"SC1","en":"Standard Clean 1 (APM)","abbr":"SC1","def":"NH₄OH:H₂O₂:H₂O 혼합액(약 1:1:5~1:4:50, 50~75 °C). 표면을 산화·식각해 입자를 들어 올리고 높은 pH의 정전 반발로 재부착을 막는다.","chapters":["cleanbasics#rca"]},
    {"ko":"SC2","en":"Standard Clean 2 (HPM)","abbr":"SC2","def":"HCl:H₂O₂:H₂O 혼합액(약 1:1:6, 70~80 °C). 낮은 pH에서 Fe·Al·Zn 같은 금속을 녹이고 염화 착물로 붙잡아 떼어 낸다. 입자 제거력은 약하다.","chapters":["cleanbasics#rca"]},
    {"ko":"피라냐 용액","en":"Sulfuric–Peroxide Mixture","abbr":"SPM","def":"H₂SO₄:H₂O₂ 고온 혼합액(약 120~150 °C). 카로산(H₂SO₅)의 강한 산화력으로 유기물·레지스트를 지운다. 황산 잔류가 남지 않게 뜨거운 물로 충분히 헹군다.","chapters":["cleanbasics#rca"]},
    {"ko":"희석 불산","en":"Diluted HF","abbr":"DHF","def":"물로 묽힌 HF(예: 1:100). 산화막과 그 속 금속을 지우고 표면을 수소로 종단한다.","chapters":["cleanbasics#rca","wetclean"]},
    {"ko":"수소 종단","en":"hydrogen termination","abbr":"","def":"HF 처리 후 실리콘 표면 결합이 수소로 막힌 상태. 소수성이며 한동안 재산화를 늦춘다.","chapters":["cleanbasics#rca"]},
    {"ko":"접촉각","en":"contact angle","abbr":"θ","def":"액체 방울이 표면과 이루는 각. 친수성은 작고 소수성은 크다. 표면 상태와 모세관력·패턴 붕괴의 핵심 변수다.","chapters":["cleanbasics#rca","wetclean#collapse"]},
    {"ko":"언더컷 리프트오프","en":"undercut lift-off","abbr":"","def":"입자 아래 표면을 살짝 식각해 부착 면적을 없애 입자를 떼는 원리. SC1·DHF의 입자 제거 메커니즘이다.","chapters":["cleanbasics#removal"]},
    {"ko":"무전해 치환 석출","en":"electroless displacement deposition","abbr":"","def":"Cu²⁺처럼 실리콘보다 귀한 금속 이온이 HF 용액에서 실리콘을 산화시키며 표면에 금속으로 석출되는 현상. 그래서 HF 단계의 금속 농도는 ppt 수준으로 관리한다.","chapters":["cleanbasics#metals"]},
    {"ko":"오존수","en":"ozonated DIW","abbr":"DIO₃","def":"오존을 녹인 초순수. 상온에서 유기물을 산화하고 얇은 산화막을 만들어 SPM을 대체한다.","chapters":["cleanbasics#sequence"]},
    {"ko":"CMP 후 세정","en":"post-CMP clean","abbr":"","def":"연마 직후 연마입자·잔류 금속·BTA 같은 유기물을 지우는 세정. 브러시·메가소닉·약액·건조를 한 장비에서 순서대로 한다.","chapters":["postclean#why"]},
    {"ko":"통합 세정기","en":"integrated cleaner","abbr":"","def":"CMP 장비에 붙어 연마 직후 젖은 웨이퍼를 받아 세정·건조까지 끝내는 모듈. CP-300은 PVA 브러시 2단 + 메가소닉(약 1 MHz) + IPA 마랑고니 건조로 dry-out을 만든다.","chapters":["postclean#cleaner"]},
    {"ko":"PVA 브러시","en":"PVA brush","abbr":"","def":"폴리비닐알코올 스펀지 브러시. 젖으면 부드러워 웨이퍼를 긁지 않고 입자를 문질러 떼어 낸다. CP-300은 약 200~400 rpm.","chapters":["postclean#brush"]},
    {"ko":"노듈","en":"nodule","abbr":"","def":"PVA 브러시 롤러 표면에 솟은 원기둥 모양 돌기. 실제로 웨이퍼에 닿는 부분이라 배열·압입이 접촉 면적과 문지름 패턴을 정하고, 닳거나 오염되면 결함이 는다.","chapters":["postclean#brush"]},
    {"ko":"브러시 압입","en":"brush compression","abbr":"","def":"브러시가 웨이퍼 면을 지나 더 눌린 깊이(CP-300 약 1 mm). 클수록 접촉 폭과 압력이 늘어 제거력이 커지지만 브러시 로딩과 마모도 빨라진다.","chapters":["postclean#brush"]},
    {"ko":"브러시 로딩","en":"brush loading","abbr":"","def":"브러시 스펀지 속에 연마입자·잔류물이 쌓여 깨끗한 웨이퍼에 다시 옮기는 상태. 결함이 서서히 늘어나는 모습으로 나타나며 브러시 자체 헹굼·약액 세척·교체 주기로 관리한다.","chapters":["postclean#brush"]},
    {"ko":"브러시 길들이기","en":"brush break-in","abbr":"","def":"새 PVA 브러시를 더미 웨이퍼와 약액으로 돌려 제조 때 남은 입자·유기물을 빼내고 접촉 상태를 안정시키는 작업(break-in). 생략하면 첫 웨이퍼들에서 입자 결함이 튄다.","chapters":["postclean#brush"]},
    {"ko":"시트르산","en":"citric acid","abbr":"","def":"약산성 CMP 후 세정액의 착화제. Cu 산화물과 금속 이온을 수용성 착물로 녹여 떼어 내지만, 지나치면 Cu를 식각해 표면이 거칠어진다.","chapters":["postclean#chem"]},
    {"ko":"TMAH","en":"tetramethylammonium hydroxide","abbr":"TMAH","def":"금속 이온이 없는 유기 강염기(수산화 테트라메틸암모늄). 알칼리 CMP 후 세정에서 입자와 표면을 모두 음전하로 만들어 정전 반발로 재부착을 막고, Na⁺·K⁺ 같은 가동 이온 오염 걱정이 없다.","chapters":["postclean#chem"]},
    {"ko":"킬레이트제","en":"chelating agent","abbr":"","def":"금속 이온을 여러 자리로 붙잡는 분자(EDTA·시트르산·아민류 등). 용액 속 금속 이온을 녹은 채 유지해 웨이퍼로 다시 석출·흡착되는 것을 막는다.","chapters":["postclean#chem"]},
    {"ko":"메가소닉","en":"megasonic cleaning","abbr":"","def":"약 1 MHz 음파로 액체를 흔드는 세정. 음향 경계층을 얇게 만들고 음향 흐름으로 작은 입자를 떼어 낸다. 과하면 캐비테이션으로 패턴이 손상된다.","chapters":["postclean#megasonic"]},
    {"ko":"음향 경계층","en":"acoustic boundary layer","abbr":"","def":"진동 흐름이 표면 근처에서 줄어드는 층 δ_ac = √(2ν/ω). 1 MHz 물에서 약 0.56 µm로 작은 입자에도 흐름이 닿는다.","chapters":["postclean#megasonic"]},
    {"ko":"음향 흐름","en":"acoustic streaming","abbr":"","def":"음파가 액체에 흡수되며 전달한 운동량으로 생기는 시간 평균 흐름. 메가소닉에서는 얇은 음향 경계층 안까지 흐름이 닿아 서브마이크로 입자에 항력을 준다.","chapters":["postclean#megasonic"]},
    {"ko":"캐비테이션","en":"cavitation (stable / transient)","abbr":"","def":"음압의 음(−) 반주기에 기포가 생겨 진동하거나(안정 캐비테이션) 크게 자랐다가 갑자기 터지는(과도 캐비테이션) 현상. 과도 캐비테이션의 제트·충격파는 입자를 떼는 힘이자 미세 패턴을 부수는 원인이다.","chapters":["postclean#megasonic"]},
    {"ko":"레일리–플레셋 방정식","en":"Rayleigh–Plesset equation","abbr":"","def":"음압 속 구형 기포 반지름 R(t)의 운동 방정식 RR̈ + (3/2)Ṙ² = (p_B − p_∞(t) − 2σ/R − 4μṘ/R)/ρ. 기포가 언제 과도하게 붕괴하는지와 붕괴 압력을 추정한다.","chapters":["postclean#megasonic"]},
    {"ko":"블레이크 문턱","en":"Blake threshold","abbr":"","def":"기포 핵이 표면장력을 이기고 무한정 자라기 시작하는 최소 음압 진폭. 핵이 작을수록 문턱이 높아, 주파수·출력·용존 가스로 과도 캐비테이션을 조절한다.","chapters":["postclean#megasonic"]},
    {"ko":"스핀 건조","en":"spin dry","abbr":"","def":"웨이퍼를 수천 rpm으로 돌려 원심력으로 물을 털어 내는 건조. 단순하지만 소수성 표면에서 물방울이 쪼개져 남으면 물반점이 생긴다.","chapters":["postclean#dry"]},
    {"ko":"마랑고니 건조","en":"Marangoni drying","abbr":"","def":"메니스커스 끝에 IPA 증기를 대어 표면장력을 낮추면(물 약 72 mN/m보다 작게) 표면장력이 높은 물 쪽으로 끄는 마랑고니 흐름이 생겨 물막을 웨이퍼에서 쓸어 낸다. 물방울 없이 말라 물반점이 거의 없다.","chapters":["postclean#dry","wetclean#drying"]},
    {"ko":"로타고니","en":"Rotagoni drying","abbr":"","def":"회전하는 웨이퍼 위에서 IPA 증기와 물 노즐을 함께 바깥으로 스캔하는 매엽식 마랑고니 건조.","chapters":["postclean#dry"]},
    {"ko":"란다우–레비치 막","en":"Landau–Levich film","abbr":"","def":"액체에서 끌어올린 판에 묻어 나오는 액막. 두께 h ≈ 0.94·ℓ_c·Ca^(2/3) (ℓ_c = √(γ/ρg), Ca = μU/γ)로 끌어올림 속도가 느릴수록 얇다. 마랑고니 건조가 이 막을 더 줄인다.","chapters":["postclean#dry"]},
    {"ko":"배치 습식 벤치","en":"batch wet bench","abbr":"","def":"카세트에 담긴 웨이퍼 수십 장을 약액조와 헹굼조에 차례로 담그는 장비. 처리량과 약액 효율이 좋지만 조를 공유해 교차 오염이 생기고 웨이퍼마다 조건을 바꿀 수 없다.","chapters":["wetclean#tools"]},
    {"ko":"매엽 스핀 세정기","en":"single-wafer spin processor","abbr":"","def":"웨이퍼 한 장씩 회전시키며 노즐로 약액과 물을 뿌리는 장비. 웨이퍼마다 조건 제어와 앞·뒷면·베벨 따로 처리가 쉽고 교차 오염이 적지만, 처리량을 위해 챔버를 여럿 둔다.","chapters":["wetclean#tools","wetclean#single"]},
    {"ko":"오버플로 린스","en":"overflow rinse","abbr":"","def":"조 바닥으로 초순수를 계속 넣어 위로 넘치게 하는 헹굼. 완전 혼합이면 농도가 C(t) = C₀·exp(−Q·t/V)로 줄어, 조 부피를 몇 번 갈아 주느냐가 헹굼 시간을 정한다.","chapters":["wetclean#rinse"]},
    {"ko":"퀵 덤프 린스","en":"Quick Dump Rinse","abbr":"QDR","def":"헹굼조를 순식간에 비웠다가 다시 채우기를 반복하는 헹굼. 한 사이클마다 웨이퍼에 남은 액막 비율만큼(예: 수 %) 농도가 떨어져, 몇 사이클로 오버플로보다 빨리 헹군다.","chapters":["wetclean#rinse"]},
    {"ko":"드래그아웃","en":"drag-out","abbr":"","def":"웨이퍼·카세트에 묻어 다음 조로 끌려 나가는 약액. 헹굼 부담과 약액 소모를 키우고 다음 조를 오염시킨다.","chapters":["wetclean#rinse","wetclean#bath"]},
    {"ko":"비저항","en":"resistivity","abbr":"","def":"물의 이온 순도 지표. 순수한 물의 한계는 25 °C에서 18.2 MΩ·cm이며, 헹굼조 출구 비저항이 이 값 가까이 회복되면 약액 이온이 다 빠졌다고 보고 헹굼을 끝낸다.","chapters":["wetclean#rinse"]},
    {"ko":"초순수","en":"Ultrapure Water","abbr":"UPW","def":"이온·유기물·입자·용존 가스를 극한까지 걷은 물(18.2 MΩ·cm, TOC 1 ppb 미만). 헹굼·약액 희석·CMP 패드 세척에 쓰며 세정 공정 물 사용량의 대부분을 차지한다.","chapters":["wetclean#footprint","cleanbasics"]},
    {"ko":"스파이킹","en":"spiking","abbr":"","def":"약액조에서 시간에 따라 줄어드는 성분(SC1의 NH₃ 증발, H₂O₂ 분해 등)을 원액으로 조금씩 보충해 농도를 되돌리는 것. 교체 주기를 늘리지만 금속·입자는 계속 쌓이므로 결국 교체가 필요하다.","chapters":["wetclean#bath"]},
    {"ko":"약액 교체","en":"bath change","abbr":"","def":"약액조를 비우고 새 약액으로 채우는 것. 금속 축적·입자·농도 저하 중 가장 먼저 한계에 이르는 항목이 주기를 정하며, 약품 사용량과 폐수량의 큰 몫이다.","chapters":["wetclean#bath"]},
    {"ko":"교차 오염","en":"cross-contamination","abbr":"","def":"한 웨이퍼·로트·공정의 오염이 다른 웨이퍼로 옮겨 가는 것. 한 조를 여러 로트가 공유하는 배치 장비에서 크고, 약액을 한 번 쓰고 버리는 매엽 장비에서 작다.","chapters":["wetclean#bath"]},
    {"ko":"EBP 식","en":"Emslie–Bonner–Peck equation","abbr":"EBP","def":"회전 원판 위 뉴턴 유체 액막이 얇아지는 해 h(t) = h₀/√(1 + 4ρω²h₀²t/(3η)). 오래 지나면 h ∝ t^(−1/2)로 얇아지며, 회전수·점도가 액막 두께와 매엽 식각 균일도를 정한다.","chapters":["wetclean#single"]},
    {"ko":"베벨 세정","en":"bevel clean","abbr":"","def":"웨이퍼 가장자리 경사면(베벨)과 뒷면 둘레에 남은 막·금속·폴리머를 가장자리에만 약액을 대어 지우는 매엽 공정. 가장자리 박리 파편과 금속 교차 오염을 막는다.","chapters":["wetclean#single"]},
    {"ko":"패턴 붕괴","en":"pattern collapse (stiction)","abbr":"","def":"건조 중 좁은 패턴 사이에 남은 액체의 라플라스 압력이 양쪽에서 다르게 걸려 높은 패턴을 휘게 하고, 붙은 패턴이 마른 뒤에도 떨어지지 않는(stiction) 결함. 종횡비·표면장력·접촉각이 좌우한다.","chapters":["wetclean#collapse"]},
    {"ko":"라플라스 압력","en":"Laplace pressure","abbr":"","def":"휘어진 액면 양쪽의 압력 차. 간격 s인 두 벽 사이에서 ΔP = 2γcosθ/s. 물(72 mN/m)·s = 20 nm에서 약 7 MPa.","chapters":["wetclean#collapse"]},
    {"ko":"임계 종횡비","en":"critical aspect ratio","abbr":"","def":"패턴이 붕괴하기 시작하는 높이/폭 비. 패턴을 외팔보로 보면 처짐이 높이의 4제곱에 비례하므로, 처짐이 간격의 절반에 이르는 종횡비를 조금만 넘어도 갑자기 무너진다.","chapters":["wetclean#collapse"]},
    {"ko":"실릴화","en":"silylation (surface modification)","abbr":"","def":"실릴화제로 표면 OH기를 실릴기로 바꿔 접촉각을 90° 가까이 올리는 처리. cosθ → 0이 되어 라플라스 압력과 패턴 붕괴 힘이 크게 줄어든다.","chapters":["wetclean#drying"]},
    {"ko":"승화 건조","en":"sublimation drying","abbr":"","def":"패턴 사이 린스액을 승화성 물질로 바꿔 굳힌 뒤 고체에서 바로 기체로 날려 보내는 건조. 액–기 계면이 패턴 사이를 지나가지 않아 모세관력이 생기지 않는다.","chapters":["wetclean#drying"]},
    {"ko":"초임계 CO₂ 건조","en":"supercritical CO₂ drying","abbr":"SCF","def":"물을 IPA로, IPA를 액체 CO₂로 치환한 뒤 임계점(31.1 °C, 7.38 MPa) 위로 올렸다가 감압해 말리는 방법. 액–기 계면이 없어 모세관력이 0이라 초고종횡비 패턴에 쓴다.","chapters":["wetclean#drying"]},
    {"ko":"극저온 에어로졸","en":"cryogenic aerosol","abbr":"","def":"Ar/N₂를 노즐에서 단열 팽창시켜 만든 고체 미립자를 표면에 부딪쳐 입자를 굴려 떼어 내는 건식 세정. 약품·물이 없지만 미세 패턴은 충돌 운동량에 손상될 수 있다.","chapters":["wetclean#dry"]},
    {"ko":"기상 HF","en":"vapor HF","abbr":"VHF","def":"HF와 수증기(또는 알코올) 증기로 산화막을 액체 없이 식각하는 방법(SiO₂ → SiF₄↑). MEMS 구조 해제나 에피 전 자연 산화막 제거처럼 액체가 닿으면 안 되는 곳에 쓴다.","chapters":["wetclean#dry"]},
    {"ko":"플라스마 애싱","en":"plasma ashing","abbr":"","def":"O₂(또는 H₂/N₂) 플라스마 라디칼로 레지스트·유기 잔류물을 CO₂·H₂O 기체로 태워 없애는 건식 공정. 무기 잔류물은 남으므로 습식 세정과 짝을 이룬다.","chapters":["wetclean#dry"]},
    {"ko":"레이저 세정","en":"laser cleaning","abbr":"","def":"나노초 펄스로 표면(또는 얇은 물막)을 순간 가열해 열팽창·증발 충격으로 입자를 튕겨 내는 세정. 레티클 세정이나 국소 결함 수리에 쓴다.","chapters":["wetclean#dry"]},
    {"ko":"하이브리드 본딩","en":"hybrid bonding","abbr":"","def":"절연막끼리(SiO₂·SiCN)와 Cu 패드끼리를 한 번에 직접 붙이는 웨이퍼·칩 접합. 솔더 범프 없이 수 µm 이하 피치를 만들며, 표면 거칠기 약 0.5 nm 이하와 Cu 높이를 nm 단위로 맞추는 CMP가 성패를 가른다.","chapters":["advanced#hybrid","overview"]},
    {"ko":"구리 리세스","en":"Cu recess","abbr":"","def":"Cu 패드 윗면이 절연막 면보다 낮게 들어간 깊이. 하이브리드 본딩에서는 상온에서 절연막이 먼저 붙도록 수 nm 리세스를 남기고, 열처리 때 Cu 팽창으로 메운다. 패드 밀도·크기에 따라 달라져 지도로 관리한다.","chapters":["advanced#recess"]},
    {"ko":"Cu 돌출","en":"Cu protrusion","abbr":"","def":"Cu 패드가 절연막 면보다 솟은 상태. 상온 절연막 접합을 막아 넓은 미접합 영역을 만들므로 하이브리드 본딩 CMP는 돌출이 없도록 약한 리세스 쪽으로 맞춘다. 컨디셔너 다이아몬드의 돌출 높이와는 다른 말이다.","chapters":["advanced#recess"]},
    {"ko":"마이크로범프","en":"micro-bump","abbr":"","def":"칩 사이를 잇는 수십 µm 피치의 작은 솔더 범프. 언더필과 솔더 젖음 때문에 약 10 µm 아래로 피치를 줄이기 어려워 하이브리드 본딩이 대안이 되었다.","chapters":["advanced#hybrid"]},
    {"ko":"열팽창 접합","en":"thermal-expansion closure","abbr":"","def":"어닐(약 200~400 °C)에서 Cu(CTE 약 17 ppm/K)가 SiO₂(약 0.5 ppm/K)보다 훨씬 많이 팽창해 리세스 틈을 메우고 Cu–Cu 확산 접합을 이루는 원리. 메울 수 있는 리세스는 패드 두께 × CTE 차 × 온도 상승 정도다.","chapters":["advanced#recess"]},
    {"ko":"접합파","en":"bond wave","abbr":"","def":"두 웨이퍼 중심을 살짝 눌러 접촉을 시작하면 표면 에너지에 끌려 바깥으로 퍼져 나가는 접합 전선. 퍼지는 동안 공기를 밀어내며, 입자나 굴곡에서 멈추면 보이드가 남는다.","chapters":["advanced#void"]},
    {"ko":"접합 보이드","en":"bonding void (Tong–Gösele)","abbr":"","def":"입자·굴곡 때문에 붙지 못한 빈 영역. Tong–Gösele 모델로 보이드 반지름 R ∝ h^(1/2)·(E·t³/γ)^(1/4) (h: 입자 높이, t: 웨이퍼 두께, γ: 접합 에너지)이며, 1 µm 입자 하나가 지름 약 1 cm 보이드를 만들 수 있다.","chapters":["advanced#void"]},
    {"ko":"웨이퍼 박화","en":"wafer thinning, backgrinding","abbr":"","def":"접합 뒤 웨이퍼 뒷면을 연삭·CMP·식각으로 수~수십 µm까지 얇게 만드는 공정. 거친 연삭 → 고운 연삭 → CMP·습식 식각으로 손상층을 걷어 낸다.","chapters":["advanced#thinning"]},
    {"ko":"총 두께 변동","en":"Total Thickness Variation","abbr":"TTV","def":"웨이퍼 한 장 안 두께의 최대 − 최소. 박화 후 남는 실리콘 두께 산포가 되어 TSV 노출 깊이와 식각 정지막 과식각량을 정한다.","chapters":["advanced#thinning"]},
    {"ko":"식각 정지막","en":"etch stop layer","abbr":"","def":"박화·뒷면 식각이 그 위에서 멈추도록 넣은 층(SiGe, 매몰 산화막 등). 연삭 TTV를 선택비로 흡수해 남는 두께를 nm 단위로 고르게 한다.","chapters":["advanced#thinning","advanced#logic"]},
    {"ko":"TSV 노출","en":"TSV reveal","abbr":"","def":"뒷면을 깎아 실리콘 관통 전극(TSV) 끝을 드러내는 공정. 실리콘을 선택적으로 식각해 TSV를 솟게 한 뒤 절연막을 덮고 CMP로 Cu를 연다.","chapters":["advanced#thinning"]},
    {"ko":"가장자리 트리밍","en":"edge trimming","abbr":"","def":"박화 전에 위 웨이퍼 가장자리 수 mm를 접합면 근처 깊이까지 미리 잘라 내는 공정. 나이프 에지가 연삭 중 깨져 웨이퍼 전체를 긁는 것을 막는다.","chapters":["advanced#thinning"]},
    {"ko":"나이프 에지","en":"knife edge","abbr":"","def":"둥근 웨이퍼 가장자리가 접합되지 않은 채 박화되어 칼날처럼 얇게 남은 부분. 깨지면 파편이 스크래치와 균열을 만든다.","chapters":["advanced#thinning"]},
    {"ko":"웨이퍼 휨","en":"wafer bow / warp","abbr":"","def":"막 응력·박화·온도 차로 웨이퍼가 굽은 정도. 보우는 중심면 중심 높이의 기준면 대비 편차, 워프는 중심면 최대 − 최소다. 크면 척킹·접합·노광 오버레이가 어려워진다.","chapters":["advanced#bow"]},
    {"ko":"스토니 식","en":"Stoney equation","abbr":"","def":"얇은 막 응력 σ_f에 의한 기판 곡률 κ = 6σ_f·t_f(1 − ν_s)/(E_s·t_s²). 기판 두께의 제곱에 반비례해 웨이퍼를 절반으로 박화하면 같은 막에서 휨이 4배가 된다.","chapters":["advanced#bow"]},
    {"ko":"게이트 올 어라운드","en":"Gate-All-Around","abbr":"GAA","def":"게이트가 나노시트 채널을 사방에서 감싸는 트랜지스터. 더미 게이트·RMG·SAC 단계마다 높이 예산이 더 빠듯해져 CMP 정밀도 요구가 커진다.","chapters":["advanced#logic","metals#rmg"]},
    {"ko":"후면 전력 공급","en":"BackSide Power Delivery Network","abbr":"BSPDN","def":"전원 배선을 웨이퍼 뒷면으로 옮겨 앞면 신호 배선의 혼잡과 IR 강하를 줄이는 구조. 캐리어 접합 → 박화 → 식각 정지 → 뒷면 CMP가 새로 필요하다.","chapters":["advanced#logic"]},
    {"ko":"가상 계측","en":"Virtual Metrology","abbr":"VM","def":"장비 센서·레시피 데이터로 측정하지 않은 웨이퍼의 두께·제거율을 통계·ML 모델로 예측하는 것. 측정 비용 없이 모든 웨이퍼에 R2R 피드백을 줄 수 있지만 학습 범위 밖에서는 틀린다.","chapters":["advanced#vm","endpoint#apc"]},
    {"ko":"디지털 트윈","en":"digital twin","abbr":"","def":"장비·공정을 물리 모델과 데이터로 복제한 가상 모델. 레시피·소모품 교체·이상을 실제 웨이퍼 없이 시험한다.","chapters":["advanced#vm"]},
    {"ko":"2.5D·3D 집적","en":"2.5D / 3D integration","abbr":"","def":"인터포저 위에 칩을 나란히 놓거나(2.5D) 칩을 수직으로 쌓아(3D) 잇는 패키징. TSV·하이브리드 본딩·박화가 모두 CMP를 요구한다.","chapters":["advanced#hybrid"]}
  ]
};
